    "subheadline": "శ్రీహరికోట సతీష్ ధావన్ అంతరిక్ష కేంద్రం నుంచి త్వరలోనే అంతరిక్షంలోకి వ్యోమగాములు.",
    "slug": "art-te-001-జాతీయం",
    "leadParagraph": "భారత అంతరిక్ష పరిశోధనా సంస్థ (ఇస్రో) చేపట్టిన ప్రతిష్టాత్మక గగన్‌యాన్ ప్రాజెక్టు తుది భూస్థాయి క్రయోజెనిక్ ఇంజిన్ పరీక్షలు విజయవంతంగా ముగిశాయి. భారత వ్యోమగాములను అంతరిక్ష కక్ష్యలోకి తీసుకెళ్లే ఎల్వీఎం-3 రాకెట్ వ్యవస్థ సర్వసన్నద్ధంగా ఉందని ఇస్రో చైర్మన్ ప్రకటించారు.",
    "summary": "భారత అంతరిక్ష పరిశోధనా సంస్థ (ఇస్రో) చేపట్టిన ప్రతిష్టాత్మక గగన్‌యాన్ ప్రాజెక్టు తుది భూస్థాయి క్రయోజెనిక్ ఇంజిన్ పరీక్షలు విజయవంతంగా ముగిశాయి. భారత వ్యోమగాములను అంతరిక్ష కక్ష్యలోకి తీసుకెళ్లే ఎల్వీఎం-3 రాకెట్ వ్యవస్థ సర్వసన్నద్ధంగా ఉందని ఇస్రో చైర్మన్ ప్రకటించారు.",
    "synopsis": "భారత అంతరిక్ష పరిశోధనా సంస్థ (ఇస్రో) చేపట్టిన ప్రతిష్టాత్మక గగన్‌యాన్ ప్రాజెక్టు తుది భూస్థాయి క్రయోజెనిక్ ఇంజిన్ పరీక్షలు విజయవంతంగా ముగిశాయి. భారత వ్యోమగాములను అంతరిక్ష కక్ష్యలోకి తీసుకెళ్లే ఎల్వీఎం-3 రాకెట్ వ్యవస్థ సర్వసన్నద్ధంగా ఉందని ఇస్రో చైర్మన్ ప్రకటించారు.",
    "bodyContent": "బెంగళూరులోని ఇస్రో ప్రధాన కార్యాలయం విడుదల చేసిన ప్రకటన ప్రకారం, నాలుగు దశల భద్రతా పరీక్షలు నూరు శాతం నిర్దేశిత ప్రమాణాలకు అనుగుణంగా సాగాయి. క్రూ మాడ్యూల్ రికవరీ సిస్టమ్ మరియు లైఫ్ సపోర్ట్ సిస్టమ్‌ల సామర్థ్యాన్ని శాస్త్రవేత్తలు క్షుణ్ణంగా సమీక్షించారు. భారతీయ వ్యోమగాములు అంతరిక్షంలో మూడు రోజుల పాటు పరిశోధనలు జరిపి సురక్షితంగా భూమికి తిరిగి వచ్చేందుకు అవసరమైన రక్షణ కవచం సిద్ధమైంది. ఈ చారిత్రక ఘట్టం స్వదేశీ అంతరిక్ష సాంకేతిక ప్రయాణంలో నూతన అధ్యాయాన్ని లిఖించనుంది.",
    "content": "బెంగళూరులోని ఇస్రో ప్రధాన కార్యాలయం విడుదల చేసిన ప్రకటన ప్రకారం, నాలుగు దశల భద్రతా పరీక్షలు నూరు శాతం నిర్దేశిత ప్రమాణాలకు అనుగుణంగా సాగాయి. క్రూ మాడ్యూల్ రికవరీ సిస్టమ్ మరియు లైఫ్ సపోర్ట్ సిస్టమ్‌ల సామర్థ్యాన్ని శాస్త్రవేత్తలు క్షుణ్ణంగా సమీక్షించారు. భారతీయ వ్యోమగాములు అంతరిక్షంలో మూడు రోజుల పాటు పరిశోధనలు జరిపి సురక్షితంగా భూమికి తిరిగి వచ్చేందుకు అవసరమైన రక్షణ కవచం సిద్ధమైంది. ఈ చారిత్రక ఘట్టం స్వదేశీ అంతరిక్ష సాంకేతిక ప్రయాణంలో నూతన అధ్యాయాన్ని లిఖించనుంది.",
