    "bodyContent": "నూతన చట్టం ప్రకారం అనుమతి లేకుండా పౌరుల బయోమెట్రిక్, ఆర్థిక లేదా వ్యక్తిగత సమాచారాన్ని సేకరించడం లేదా విదేశీ సర్వర్లలో నిల్వ చేయడం చట్టరీత్యా నేరం. డేటా ఉల్లంఘనలకు పాల్పడే సోషల్ మీడియా, టెక్ దిగ్గజాలకు భారీ జరిమానాలు విధించనున్నారు. డిజిటల్ ఇండియా రంగంలో పారదర్శకతతో పాటు అంతర్జాతీయ పెట్టుబడులకు అనువైన విశ్వసనీయ వాతావరణం ఏర్పడుతుందని కేంద్ర ఐటీ శాఖ మంత్రి పార్లమెంట్‌లో స్పష్టం చేశారు.",
