    "leadParagraph": "దేశంలోని సామాన్య పౌరులకు సత్వర విచారణ, న్యాయం అందడం రాజ్యాంగం కల్పించిన ప్రాథమిక హక్కని సుప్రీంకోర్టు రాజ్యాంగ ధర్మాసనం సంచలన తీర్పును వెలువరించింది.",
    "summary": "దేశంలోని సామాన్య పౌరులకు సత్వర విచారణ, న్యాయం అందడం రాజ్యాంగం కల్పించిన ప్రాథమిక హక్కని సుప్రీంకోర్టు రాజ్యాంగ ధర్మాసనం సంచలన తీర్పును వెలువరించింది.",
    "synopsis": "దేశంలోని సామాన్య పౌరులకు సత్వర విచారణ, న్యాయం అందడం రాజ్యాంగం కల్పించిన ప్రాథమిక హక్కని సుప్రీంకోర్టు రాజ్యాంగ ధర్మాసనం సంచలన తీర్పును వెలువరించింది.",
    "bodyContent": "దేశవ్యాప్తంగా అపరిష్కృతంగా ఉన్న కోట్ల కొద్దీ కేసుల పరిష్కారానికి సమగ్ర కాలపరిమితిని సుప్రీంకోర్టు నిర్దేశించింది. జిల్లా, సెషన్స్ న్యాయస్థానాలను హైస్పీడ్ ఆప్టికల్ ఫైబర్ ద్వారా అనుసంధానం చేయాలని రాష్ట్ర ప్రభుత్వాలకు ఆదేశాలు జారీ అయ్యాయి. వర్చువల్ కోర్టులు, ఈ-ఫైలింగ్ ద్వారా పేద ప్రజలకు సైతం ఉచిత న్యాయ సహాయం అందించే వ్యవస్థను పటిష్టం చేయాలని ప్రధాన న్యాయమూర్తి నేతృత్వంలోని ధర్మాసనం పేర్కొంది.",
    "content": "దేశవ్యాప్తంగా అపరిష్కృతంగా ఉన్న కోట్ల కొద్దీ కేసుల పరిష్కారానికి సమగ్ర కాలపరిమితిని సుప్రీంకోర్టు నిర్దేశించింది. జిల్లా, సెషన్స్ న్యాయస్థానాలను హైస్పీడ్ ఆప్టికల్ ఫైబర్ ద్వారా అనుసంధానం చేయాలని రాష్ట్ర ప్రభుత్వాలకు ఆదేశాలు జారీ అయ్యాయి. వర్చువల్ కోర్టులు, ఈ-ఫైలింగ్ ద్వారా పేద ప్రజలకు సైతం ఉచిత న్యాయ సహాయం అందించే వ్యవస్థను పటిష్టం చేయాలని ప్రధాన న్యాయమూర్తి నేతృత్వంలోని ధర్మాసనం పేర్కొంది.",
