    "articleId": "art-te-004",
    "tenantId": "tenant-metro-chronicle",
    "headline": "భారత రక్షణ రంగానికి బలం: స్వదేశీ తేజస్ మార్క్-2 యుద్ధ విమానాల తొలి విమాన పరీక్ష",
    "title": "భారత రక్షణ రంగానికి బలం: స్వదేశీ తేజస్ మార్క్-2 యుద్ధ విమానాల తొలి విమాన పరీక్ష",
    "subheadline": "హిందుస్థాన్ ఏరోనాటిక్స్ లిమిటెడ్ (హెచ్ఏఎల్) ఆధ్వర్యంలో గగనతలంలో అద్భుత విన్యాసాలు.",
    "slug": "art-te-004-జాతీయం",
    "leadParagraph": "పూర్తిగా భారత్‌లోనే రూపుదిద్దుకున్న తేజస్ మార్క్-2 అత్యాధునిక మల్టీరోల్ యుద్ధ విమానం తొలి ట్రయల్ రన్ విజయవంతమైంది. అధునాతన ఏఈఎస్ఏ రాడార్, అధునాతన క్షిపణులను ప్రయోగించగల సత్తా దీని ప్రత్యేకత.",
    "summary": "పూర్తిగా భారత్‌లోనే రూపుదిద్దుకున్న తేజస్ మార్క్-2 అత్యాధునిక మల్టీరోల్ యుద్ధ విమానం తొలి ట్రయల్ రన్ విజయవంతమైంది. అధునాతన ఏఈఎస్ఏ రాడార్, అధునాతన క్షిపణులను ప్రయోగించగల సత్తా దీని ప్రత్యేకత.",
    "synopsis": "పూర్తిగా భారత్‌లోనే రూపుదిద్దుకున్న తేజస్ మార్క్-2 అత్యాధునిక మల్టీరోల్ యుద్ధ విమానం తొలి ట్రయల్ రన్ విజయవంతమైంది. అధునాతన ఏఈఎస్ఏ రాడార్, అధునాతన క్షిపణులను ప్రయోగించగల సత్తా దీని ప్రత్యేకత.",
    "bodyContent": "రక్షణ శాఖ తెలిపిన వివరాల ప్రకారం, ఈ విమానం శత్రుదేశాల రాడార్లను ఏమార్చే స్టెల్త్ సాంకేతికతను కలిగి ఉంది. గంటకు 2000 కిలోమీటర్ల వేగంతో ప్రయాణించగల సామర్థ్యం దీని సొంతం. భారత్-పాక్ సరిహద్దులతో పాటు హిందూ మహాసముద్ర తీర ప్రాంతాల్లో గగనతల నిఘా కోసం వీటిని మోహరించనున్నారు. ఆత్మనిర్భర్ భారత్ లక్ష్యాల్లో భాగంగా రక్షణ ఉత్పత్తుల ఎగుమతిదారుగా భారత్ నిలవడానికి ఇది పెద్ద ముందడుగు.",
    "content": "రక్షణ శాఖ తెలిపిన వివరాల ప్రకారం, ఈ విమానం శత్రుదేశాల రాడార్లను ఏమార్చే స్టెల్త్ సాంకేతికతను కలిగి ఉంది. గంటకు 2000 కిలోమీటర్ల వేగంతో ప్రయాణించగల సామర్థ్యం దీని సొంతం. భారత్-పాక్ సరిహద్దులతో పాటు హిందూ మహాసముద్ర తీర ప్రాంతాల్లో గగనతల నిఘా కోసం వీటిని మోహరించనున్నారు. ఆత్మనిర్భర్ భారత్ లక్ష్యాల్లో భాగంగా రక్షణ ఉత్పత్తుల ఎగుమతిదారుగా భారత్ నిలవడానికి ఇది పెద్ద ముందడుగు.",
