    "summary": "రైల్వే ప్రయాణికులకు ప్రపంచ స్థాయి ప్రయాణ అనుభవాన్ని అందించే లక్ష్యంతో భారతీయ రైల్వేలు నూతనంగా రూపొందించిన 20 వందే భారత్ స్లీపర్ రైళ్లను ప్రధాని వర్చువల్ పద్ధతిలో ప్రారంభించారు.",
    "synopsis": "రైల్వే ప్రయాణికులకు ప్రపంచ స్థాయి ప్రయాణ అనుభవాన్ని అందించే లక్ష్యంతో భారతీయ రైల్వేలు నూతనంగా రూపొందించిన 20 వందే భారత్ స్లీపర్ రైళ్లను ప్రధాని వర్చువల్ పద్ధతిలో ప్రారంభించారు.",
    "bodyContent": "ఈ రైళ్లలో ఏరోడైనమిక్ డిజైన్, ఆటోమేటిక్ డోర్లు, శబ్దం రహిత ప్రయాణం మరియు సరికొత్త బయో-వాక్యూమ్ టాయిలెట్లు అమర్చబడ్డాయి. తెలుగు రాష్ట్రాలైన ఆంధ్రప్రదేశ్, తెలంగాణలకు అనుసంధానంగా ఢిల్లీ, బెంగళూరు, చెన్నై మార్గాల్లో ప్రత్యేక సర్వీసులు కేటాయించారు. గంటకు 160 కి.మీ వేగంతో దూసుకెళ్లే ఈ రైళ్ల ద్వారా ప్రయాణ సమయం దాదాపు 30 శాతం తగ్గనుంది.",
    "content": "ఈ రైళ్లలో ఏరోడైనమిక్ డిజైన్, ఆటోమేటిక్ డోర్లు, శబ్దం రహిత ప్రయాణం మరియు సరికొత్త బయో-వాక్యూమ్ టాయిలెట్లు అమర్చబడ్డాయి. తెలుగు రాష్ట్రాలైన ఆంధ్రప్రదేశ్, తెలంగాణలకు అనుసంధానంగా ఢిల్లీ, బెంగళూరు, చెన్నై మార్గాల్లో ప్రత్యేక సర్వీసులు కేటాయించారు. గంటకు 160 కి.మీ వేగంతో దూసుకెళ్లే ఈ రైళ్ల ద్వారా ప్రయాణ సమయం దాదాపు 30 శాతం తగ్గనుంది.",
