    "tenantId": "tenant-metro-chronicle",
    "headline": "పర్యావరణహిత హరిత ఇంధనం: థార్ ఎడారిలో ఆసియాలోనే అతిపెద్ద సోలార్ పార్క్",
    "title": "పర్యావరణహిత హరిత ఇంధనం: థార్ ఎడారిలో ఆసియాలోనే అతిపెద్ద సోలార్ పార్క్",
    "subheadline": "5000 మెగావాట్ల క్లీన్ ఎనర్జీ గ్రిడ్‌కు అనుసంధానం; కర్బన ఉద్గారాల తగ్గింపులో భారత్ ముందంజ.",
    "slug": "art-te-008-జాతీయం",
    "leadParagraph": "పునరుత్పాదక ఇంధన ఉత్పత్తిలో భారతదేశం సరికొత్త చరిత్ర సృష్టించింది. థార్ ఎడారి ప్రాంతంలో విస్తరించిన మెగా సోలార్ ప్రాజెక్ట్ వాణిజ్య ఉత్పత్తిని ప్రారంభించింది.",
    "summary": "పునరుత్పాదక ఇంధన ఉత్పత్తిలో భారతదేశం సరికొత్త చరిత్ర సృష్టించింది. థార్ ఎడారి ప్రాంతంలో విస్తరించిన మెగా సోలార్ ప్రాజెక్ట్ వాణిజ్య ఉత్పత్తిని ప్రారంభించింది.",
    "synopsis": "పునరుత్పాదక ఇంధన ఉత్పత్తిలో భారతదేశం సరికొత్త చరిత్ర సృష్టించింది. థార్ ఎడారి ప్రాంతంలో విస్తరించిన మెగా సోలార్ ప్రాజెక్ట్ వాణిజ్య ఉత్పత్తిని ప్రారంభించింది.",
    "bodyContent": "ఈ సౌర విద్యుత్ ప్రాజెక్ట్ ద్వారా రోజుకు లక్షలాది గృహాలకు పర్యావరణహిత విద్యుత్ అందుతుంది. పీఎం సూర్య ఘర్ ఉచిత విద్యుత్ యోజనతో పాటు నేషనల్ సోలార్ మిషన్ కింద దేశవ్యాప్తంగా థర్మల్ విద్యుత్‌పై ఆధారపడటం క్రమంగా తగ్గుతోంది. ఈ భారీ ప్లాంట్ ద్వారా సుమారు 20 లక్షల టన్నుల బొగ్గు వినియోగం తగ్గడమే కాక, వేలాది మంది ఇంజనీర్లు, సాంకేతిక నిపుణులకు ఉపాధి దక్కింది.",
    "content": "ఈ సౌర విద్యుత్ ప్రాజెక్ట్ ద్వారా రోజుకు లక్షలాది గృహాలకు పర్యావరణహిత విద్యుత్ అందుతుంది. పీఎం సూర్య ఘర్ ఉచిత విద్యుత్ యోజనతో పాటు నేషనల్ సోలార్ మిషన్ కింద దేశవ్యాప్తంగా థర్మల్ విద్యుత్‌పై ఆధారపడటం క్రమంగా తగ్గుతోంది. ఈ భారీ ప్లాంట్ ద్వారా సుమారు 20 లక్షల టన్నుల బొగ్గు వినియోగం తగ్గడమే కాక, వేలాది మంది ఇంజనీర్లు, సాంకేతిక నిపుణులకు ఉపాధి దక్కింది.",
