    "summary": "దేశంలో లాజిస్టిక్స్ ఖర్చులను తగ్గించేందుకు ఎన్‌హెచ్‌ఏఐ నిర్మిస్తున్న మల్టీలేన్ గ్రీన్ ఎక్స్‌ప్రెస్‌వేలు ప్రయాణ దూరాన్ని భారీగా తగ్గిస్తున్నాయి.",
    "synopsis": "దేశంలో లాజిస్టిక్స్ ఖర్చులను తగ్గించేందుకు ఎన్‌హెచ్‌ఏఐ నిర్మిస్తున్న మల్టీలేన్ గ్రీన్ ఎక్స్‌ప్రెస్‌వేలు ప్రయాణ దూరాన్ని భారీగా తగ్గిస్తున్నాయి.",
    "bodyContent": "అధునాతన రసాయన కాంక్రీట్ మిశ్రమాలు, సెన్సార్లతో కూడిన ఫాస్టాగ్ టోల్ బూత్‌లు, ప్రమాద రహిత ఇంటెలిజెంట్ ట్రాఫిక్ మేనేజ్‌మెంట్ సిస్టమ్ (ఐటీఎంఎస్) ద్వారా ఈ రహదారులు నిర్మించబడుతున్నాయి. సరుకు రవాణా ట్రక్కులు సగటున గంటకు 90 కిమీ వేగంతో ప్రయాణించగలగడంతో రవాణా సమయం సగానికి తగ్గింది. ఇది పారిశ్రామిక ఎగుమతులకు సరికొత్త ఉత్తేజాన్ని ఇస్తోంది.",
    "content": "అధునాతన రసాయన కాంక్రీట్ మిశ్రమాలు, సెన్సార్లతో కూడిన ఫాస్టాగ్ టోల్ బూత్‌లు, ప్రమాద రహిత ఇంటెలిజెంట్ ట్రాఫిక్ మేనేజ్‌మెంట్ సిస్టమ్ (ఐటీఎంఎస్) ద్వారా ఈ రహదారులు నిర్మించబడుతున్నాయి. సరుకు రవాణా ట్రక్కులు సగటున గంటకు 90 కిమీ వేగంతో ప్రయాణించగలగడంతో రవాణా సమయం సగానికి తగ్గింది. ఇది పారిశ్రామిక ఎగుమతులకు సరికొత్త ఉత్తేజాన్ని ఇస్తోంది.",
