    "headline": "సెమీకండక్టర్ మిషన్: భారత్‌లో మొట్టమొదటి కమర్షియల్ మైక్రోచిప్ ఫ్యాబ్రికేషన్ ప్లాంట్",
    "title": "సెమీకండక్టర్ మిషన్: భారత్‌లో మొట్టమొదటి కమర్షియల్ మైక్రోచిప్ ఫ్యాబ్రికేషన్ ప్లాంట్",
    "subheadline": "టాటా ఎలక్ట్రానిక్స్ ఆధ్వర్యంలో రూ. 91,000 కోట్ల పెట్టుబడి; అంతర్జాతీయ ఎలక్ట్రానిక్స్ హబ్‌గా భారత్.",
    "slug": "art-te-013-జాతీయం",
    "leadParagraph": "స్మార్ట్‌ఫోన్లు, ఆటోమొబైల్స్, కృత్రిమ మేధస్సు (AI) పరికరాలకు ప్రాణాధారమైన మైక్రోచిప్‌లను స్వదేశంలోనే తయారు చేసే తొలి మెగా సెమీకండక్టర్ ఫ్యాబ్ నిర్మాణం పూర్తి చేసుకుంది.",
    "summary": "స్మార్ట్‌ఫోన్లు, ఆటోమొబైల్స్, కృత్రిమ మేధస్సు (AI) పరికరాలకు ప్రాణాధారమైన మైక్రోచిప్‌లను స్వదేశంలోనే తయారు చేసే తొలి మెగా సెమీకండక్టర్ ఫ్యాబ్ నిర్మాణం పూర్తి చేసుకుంది.",
    "synopsis": "స్మార్ట్‌ఫోన్లు, ఆటోమొబైల్స్, కృత్రిమ మేధస్సు (AI) పరికరాలకు ప్రాణాధారమైన మైక్రోచిప్‌లను స్వదేశంలోనే తయారు చేసే తొలి మెగా సెమీకండక్టర్ ఫ్యాబ్ నిర్మాణం పూర్తి చేసుకుంది.",
    "bodyContent": "తైవాన్ సంస్థ సహకారంతో నిర్మించిన ఈ ప్లాంట్‌లో నెలకు 50,000 సిలికాన్ వేఫర్లను ఉత్పత్తి చేయనున్నారు. విదేశీ దిగుమతులపై ఆధారపడటం తగ్గడమే కాక, గ్లోబల్ సరఫరా గొలుసులో భారతదేశం స్వయం సమృద్ధిని సాధిస్తుంది. స్థానికంగా 25 వేల మందికి పైగా ఉన్నత స్థాయి ఇంజనీరింగ్ ఉద్యోగాలు లభించనున్నాయి.",
    "content": "తైవాన్ సంస్థ సహకారంతో నిర్మించిన ఈ ప్లాంట్‌లో నెలకు 50,000 సిలికాన్ వేఫర్లను ఉత్పత్తి చేయనున్నారు. విదేశీ దిగుమతులపై ఆధారపడటం తగ్గడమే కాక, గ్లోబల్ సరఫరా గొలుసులో భారతదేశం స్వయం సమృద్ధిని సాధిస్తుంది. స్థానికంగా 25 వేల మందికి పైగా ఉన్నత స్థాయి ఇంజనీరింగ్ ఉద్యోగాలు లభించనున్నాయి.",
