    "tenantId": "tenant-metro-chronicle",
    "headline": "జాతీయ విద్యా విధానం: ప్రాథమిక పాఠశాలల్లో మాతృభాషలోనే బోధన తప్పనిసరి",
    "title": "జాతీయ విద్యా విధానం: ప్రాథమిక పాఠశాలల్లో మాతృభాషలోనే బోధన తప్పనిసరి",
    "subheadline": "తెలుగుతో పాటు అన్ని ప్రాంతీయ భాషల్లో ప్రామాణిక సైన్స్, గణిత పాఠ్యపుస్తకాలు విడుదల.",
    "slug": "art-te-016-జాతీయం",
    "leadParagraph": "బాల్యంలో విద్యార్థుల ఆలోచనాశక్తి వికసించాలంటే మాతృభాషలోనే విద్యనభ్యసించాలని జాతీయ విద్యా కమిషన్ స్పష్టం చేసింది.",
    "summary": "బాల్యంలో విద్యార్థుల ఆలోచనాశక్తి వికసించాలంటే మాతృభాషలోనే విద్యనభ్యసించాలని జాతీయ విద్యా కమిషన్ స్పష్టం చేసింది.",
    "synopsis": "బాల్యంలో విద్యార్థుల ఆలోచనాశక్తి వికసించాలంటే మాతృభాషలోనే విద్యనభ్యసించాలని జాతీయ విద్యా కమిషన్ స్పష్టం చేసింది.",
    "bodyContent": "ప్రాథమిక స్థాయి నుంచి ఐదో తరగతి వరకు మాతృభాషలో ప్రావీణ్యం పొందిన విద్యార్థులు ఉన్నత తరగతుల్లో తార్కిక నైపుణ్యాలను సులభంగా అలవరచుకుంటున్నారని పరిశోధనలు వెల్లడిస్తున్నాయి. ఇంజనీరింగ్, మెడిసిన్ కోర్సుల పాఠ్యపుస్తకాలను సైతం తెలుగు భాషలోకి అనువదించి అందుబాటులోకి తెచ్చినట్లు విద్యాశాఖ ప్రకటించింది.",
    "content": "ప్రాథమిక స్థాయి నుంచి ఐదో తరగతి వరకు మాతృభాషలో ప్రావీణ్యం పొందిన విద్యార్థులు ఉన్నత తరగతుల్లో తార్కిక నైపుణ్యాలను సులభంగా అలవరచుకుంటున్నారని పరిశోధనలు వెల్లడిస్తున్నాయి. ఇంజనీరింగ్, మెడిసిన్ కోర్సుల పాఠ్యపుస్తకాలను సైతం తెలుగు భాషలోకి అనువదించి అందుబాటులోకి తెచ్చినట్లు విద్యాశాఖ ప్రకటించింది.",
