    "articleId": "art-te-017",
    "tenantId": "tenant-metro-chronicle",
    "headline": "భారత నౌకాదళంలోకి స్వదేశీ అణు జలాంతర్గామి ఐఎన్ఎస్ అరిఘాట్ చేరిక",
    "title": "భారత నౌకాదళంలోకి స్వదేశీ అణు జలాంతర్గామి ఐఎన్ఎస్ అరిఘాట్ చేరిక",
    "subheadline": "హిందూ మహాసముద్రంలో నిరంతర నిఘా; శత్రుదేశాల కదలికలను తిప్పికొట్టే అమోఘ శక్తి.",
    "slug": "art-te-017-జాతీయం",
    "leadParagraph": "భారత నావికాదళం అమ్ములపొదిలో మరో అణు అస్త్రం చేరింది. విశాఖపట్నం షిప్‌బిల్డింగ్ సెంటర్‌లో నిర్మించిన అణుశక్తి జలాంతర్గామి జాతికి అంకితమైంది.",
    "summary": "భారత నావికాదళం అమ్ములపొదిలో మరో అణు అస్త్రం చేరింది. విశాఖపట్నం షిప్‌బిల్డింగ్ సెంటర్‌లో నిర్మించిన అణుశక్తి జలాంతర్గామి జాతికి అంకితమైంది.",
    "synopsis": "భారత నావికాదళం అమ్ములపొదిలో మరో అణు అస్త్రం చేరింది. విశాఖపట్నం షిప్‌బిల్డింగ్ సెంటర్‌లో నిర్మించిన అణుశక్తి జలాంతర్గామి జాతికి అంకితమైంది.",
    "bodyContent": "ఈ జలాంతర్గామి నెలల తరబడి సముద్ర గర్భంలో మునిగి ఉంటూ రహస్యంగా లక్ష్యాలను ఛేదించగలదు. బాలిస్టిక్ క్షిపణులను ప్రయోగించే సామర్థ్యం దీనికి ఉంది. భారతదేశ సముద్ర సరిహద్దులను అభేద్యంగా తీర్చిదిద్దడంలో ఇది కీలక పాత్ర పోషిస్తుందని రక్షణ రంగ నిపుణులు కొనియాడారు.",
    "content": "ఈ జలాంతర్గామి నెలల తరబడి సముద్ర గర్భంలో మునిగి ఉంటూ రహస్యంగా లక్ష్యాలను ఛేదించగలదు. బాలిస్టిక్ క్షిపణులను ప్రయోగించే సామర్థ్యం దీనికి ఉంది. భారతదేశ సముద్ర సరిహద్దులను అభేద్యంగా తీర్చిదిద్దడంలో ఇది కీలక పాత్ర పోషిస్తుందని రక్షణ రంగ నిపుణులు కొనియాడారు.",
