    "headline": "ప్రధాన మంత్రి ఫసల్ బీమా యోజన నిబంధనల సరళీకరణ: 72 గంటల్లోనే పంట నష్టపరిహారం",
    "title": "ప్రధాన మంత్రి ఫసల్ బీమా యోజన నిబంధనల సరళీకరణ: 72 గంటల్లోనే పంట నష్టపరిహారం",
    "subheadline": "ఉపగ్రహ ఛాయాచిత్రాలు, డ్రోన్ సర్వేల ద్వారా నష్ట అంచనా; నేరుగా అన్నదాతల అకౌంట్లలోకి నగదు.",
    "slug": "art-te-019-జాతీయం",
    "leadParagraph": "అకాల వర్షాలు, తుపాన్లు, కరవు వంటి ప్రకృతి వైపరీత్యాల వల్ల పంట నష్టపోయిన అన్నదాతలను ఆదుకునేందుకు బీమా క్లెయిమ్ ప్రక్రియను కేంద్రం పూర్తిగా డిజిటలైజ్ చేసింది.",
    "summary": "అకాల వర్షాలు, తుపాన్లు, కరవు వంటి ప్రకృతి వైపరీత్యాల వల్ల పంట నష్టపోయిన అన్నదాతలను ఆదుకునేందుకు బీమా క్లెయిమ్ ప్రక్రియను కేంద్రం పూర్తిగా డిజిటలైజ్ చేసింది.",
    "synopsis": "అకాల వర్షాలు, తుపాన్లు, కరవు వంటి ప్రకృతి వైపరీత్యాల వల్ల పంట నష్టపోయిన అన్నదాతలను ఆదుకునేందుకు బీమా క్లెయిమ్ ప్రక్రియను కేంద్రం పూర్తిగా డిజిటలైజ్ చేసింది.",
    "bodyContent": "రైతులు స్వయంగా తమ మొబైల్ యాప్ ద్వారా పంట నష్టం ఫోటోలను అప్‌లోడ్ చేయవచ్చు. డ్రోన్ సర్వే ద్వారా 24 గంటల్లో నష్ట తీవ్రతను నిర్ధారించి, మూడో రోజుకల్లా క్లెయిమ్ అమౌంట్ జమ చేయబడుతుంది. దీనివల్ల మధ్యవర్తుల బెడద తొలగిపోయి రైతులకు సకాలంలో ఊరట లభిస్తుంది.",
    "content": "రైతులు స్వయంగా తమ మొబైల్ యాప్ ద్వారా పంట నష్టం ఫోటోలను అప్‌లోడ్ చేయవచ్చు. డ్రోన్ సర్వే ద్వారా 24 గంటల్లో నష్ట తీవ్రతను నిర్ధారించి, మూడో రోజుకల్లా క్లెయిమ్ అమౌంట్ జమ చేయబడుతుంది. దీనివల్ల మధ్యవర్తుల బెడద తొలగిపోయి రైతులకు సకాలంలో ఊరట లభిస్తుంది.",
