    "headline": "ఆర్బీఐ ద్రవ్య పరపతి సమీక్ష: రెపో రేటు యథాతథం, గృహ రుణ గ్రహీతలకు ఊరట",
    "title": "ఆర్బీఐ ద్రవ్య పరపతి సమీక్ష: రెపో రేటు యథాతథం, గృహ రుణ గ్రహీతలకు ఊరట",
    "subheadline": "ద్రవ్యోల్బణం అదుపులోనే ఉంది; భారత జీడీపీ వృద్ధి రేటు 7.2 శాతంగా అంచనా వేసిన రిజర్వ్ బ్యాంక్.",
    "slug": "art-te-020-జాతీయం",
    "leadParagraph": "రిజర్వ్ బ్యాంక్ ఆఫ్ ఇండియా (ఆర్బీఐ) ద్రవ్య పరపతి కమిటీ సమావేశంలో కీలక వడ్డీ రేట్లను మార్చకుండా యథాతథంగా కొనసాగించాలని నిర్ణయించారు.",
    "summary": "రిజర్వ్ బ్యాంక్ ఆఫ్ ఇండియా (ఆర్బీఐ) ద్రవ్య పరపతి కమిటీ సమావేశంలో కీలక వడ్డీ రేట్లను మార్చకుండా యథాతథంగా కొనసాగించాలని నిర్ణయించారు.",
    "synopsis": "రిజర్వ్ బ్యాంక్ ఆఫ్ ఇండియా (ఆర్బీఐ) ద్రవ్య పరపతి కమిటీ సమావేశంలో కీలక వడ్డీ రేట్లను మార్చకుండా యథాతథంగా కొనసాగించాలని నిర్ణయించారు.",
    "bodyContent": "బ్యాంకింగ్ రంగంలో నిరర్థక ఆస్తులు (ఎన్‌పీఏలు) కనిష్ట స్థాయికి పడిపోయాయని ఆర్బీఐ గవర్నర్ స్పష్టం చేశారు. రిటైల్ రుణాలకు డిమాండ్ స్థిరంగా ఉందని, పారిశ్రామిక రంగానికి తగినంత నగదు లభ్యత ఉందని పేర్కొన్నారు. గృహ, వాహన రుణాల ఈఎంఐలు పెరగకపోవడం మధ్యతరగతి ప్రజలకు ఉపశమనం కలిగించింది.",
    "content": "బ్యాంకింగ్ రంగంలో నిరర్థక ఆస్తులు (ఎన్‌పీఏలు) కనిష్ట స్థాయికి పడిపోయాయని ఆర్బీఐ గవర్నర్ స్పష్టం చేశారు. రిటైల్ రుణాలకు డిమాండ్ స్థిరంగా ఉందని, పారిశ్రామిక రంగానికి తగినంత నగదు లభ్యత ఉందని పేర్కొన్నారు. గృహ, వాహన రుణాల ఈఎంఐలు పెరగకపోవడం మధ్యతరగతి ప్రజలకు ఉపశమనం కలిగించింది.",
