    "headline": "దేశీయ విమానయాన రంగంలో రికార్డు: ఉడాన్ పథకంలో మరో 50 కొత్త ఎయిర్‌పోర్టులు సిద్ధం",
    "title": "దేశీయ విమానయాన రంగంలో రికార్డు: ఉడాన్ పథకంలో మరో 50 కొత్త ఎయిర్‌పోర్టులు సిద్ధం",
    "subheadline": "చిన్న పట్టణాల ప్రజలకూ విమాన ప్రయాణం చేరువ; పర్యాటక, వాణిజ్య నగరాలకు నేరుగా కనెక్టివిటీ.",
    "slug": "art-te-021-జాతీయం",
    "leadParagraph": "సామాన్య పౌరుడికి కూడా విమాన ప్రయాణం సాధ్యం కావాలనే లక్ష్యంతో చేపట్టిన ఉడాన్ పథకం కింద టైర్-2, టైర్-3 నగరాల్లో నూతన ఎయిర్‌స్ట్రిప్పులు సిద్ధమయ్యాయి.",
    "summary": "సామాన్య పౌరుడికి కూడా విమాన ప్రయాణం సాధ్యం కావాలనే లక్ష్యంతో చేపట్టిన ఉడాన్ పథకం కింద టైర్-2, టైర్-3 నగరాల్లో నూతన ఎయిర్‌స్ట్రిప్పులు సిద్ధమయ్యాయి.",
    "synopsis": "సామాన్య పౌరుడికి కూడా విమాన ప్రయాణం సాధ్యం కావాలనే లక్ష్యంతో చేపట్టిన ఉడాన్ పథకం కింద టైర్-2, టైర్-3 నగరాల్లో నూతన ఎయిర్‌స్ట్రిప్పులు సిద్ధమయ్యాయి.",
    "bodyContent": "కడప, కర్నూలు, రాజమండ్రి, వరంగల్ వంటి ప్రాంతీయ నగరాల నుంచి మెట్రో నగరాలకు డైరెక్ట్ విమాన సర్వీసులు గణనీయంగా పెరిగాయి. దేశీయ ప్యాసింజర్ ట్రాఫిక్ ఏటా 15 శాతం వృద్ధి నమోదు చేస్తూ ప్రపంచంలోనే మూడో అతిపెద్ద విమానయాన మార్కెట్‌గా భారత్ రికార్డు సృష్టించింది.",
    "content": "కడప, కర్నూలు, రాజమండ్రి, వరంగల్ వంటి ప్రాంతీయ నగరాల నుంచి మెట్రో నగరాలకు డైరెక్ట్ విమాన సర్వీసులు గణనీయంగా పెరిగాయి. దేశీయ ప్యాసింజర్ ట్రాఫిక్ ఏటా 15 శాతం వృద్ధి నమోదు చేస్తూ ప్రపంచంలోనే మూడో అతిపెద్ద విమానయాన మార్కెట్‌గా భారత్ రికార్డు సృష్టించింది.",
