    "headline": "స్టార్టప్ ఇండియా దశాబ్ది ఉత్సవాలు: ప్రపంచంలోనే మూడో అతిపెద్ద యునికార్న్ కేంద్రంగా భారత్",
    "title": "స్టార్టప్ ఇండియా దశాబ్ది ఉత్సవాలు: ప్రపంచంలోనే మూడో అతిపెద్ద యునికార్న్ కేంద్రంగా భారత్",
    "subheadline": "115 దాటిన యునికార్న్ సంస్థలు; టైర్-2 నగరాల నుంచి సైతం లక్ష కోట్ల విలువైన ఆవిష్కరణలు.",
    "slug": "art-te-022-జాతీయం",
    "leadParagraph": "భారతీయ యువత ఉద్యోగార్థులుగా కాకుండా ఉద్యోగ ప్రదాతలుగా మారాలన్న సంకల్పం ఘన విజయం సాధించింది. స్టార్టప్ ఇండియా పథకం పదేళ్ల మైలురాయిని అధిగమించింది.",
    "summary": "భారతీయ యువత ఉద్యోగార్థులుగా కాకుండా ఉద్యోగ ప్రదాతలుగా మారాలన్న సంకల్పం ఘన విజయం సాధించింది. స్టార్టప్ ఇండియా పథకం పదేళ్ల మైలురాయిని అధిగమించింది.",
    "synopsis": "భారతీయ యువత ఉద్యోగార్థులుగా కాకుండా ఉద్యోగ ప్రదాతలుగా మారాలన్న సంకల్పం ఘన విజయం సాధించింది. స్టార్టప్ ఇండియా పథకం పదేళ్ల మైలురాయిని అధిగమించింది.",
    "bodyContent": "డీప్‌టెక్, క్లైమేట్‌టెక్, అగ్రిటెక్ మరియు హెల్త్‌టెక్ విభాగాల్లో భారతీయ యువ స్టార్టప్‌లు ప్రపంచ దృష్టిని ఆకర్షిస్తున్నాయి. మహిళా పారిశ్రామికవేత్తల సంఖ్య 45 శాతానికి పైగా పెరిగింది. దేశంలో సులభతర వాణిజ్యం (ఈజ్ ఆఫ్ డూయింగ్ బిజినెస్) నూతన పరిశ్రమల స్థాపనకు గొప్ప వేదికైంది.",
