    "subheadline": "మురుగునీటి శుద్ధి కేంద్రాల ఏర్పాటు విజయవంతం; నదీ పరీవాహక ప్రాంతాల్లో ఎకో-టూరిజం అభివృద్ధి.",
    "slug": "art-te-023-జాతీయం",
