    "summary": "పవిత్ర గంగా నదిని కాలుష్య రహితంగా మార్చేందుకు కేంద్ర ప్రభుత్వం చేపట్టిన నమామి గంగే ప్రాజెక్టు అద్భుత పర్యావరణ ఫలితాలను సాధించింది.",
    "synopsis": "పవిత్ర గంగా నదిని కాలుష్య రహితంగా మార్చేందుకు కేంద్ర ప్రభుత్వం చేపట్టిన నమామి గంగే ప్రాజెక్టు అద్భుత పర్యావరణ ఫలితాలను సాధించింది.",
    "bodyContent": "ఉత్తరాఖండ్ నుంచి పశ్చిమ బెంగాల్ వరకు ఏర్పాటు చేసిన 300కు పైగా మురుగునీటి శుద్ధి ప్లాంట్ల వల్ల పారిశ్రామిక వ్యర్థాలు నదిలోకి చేరకుండా అడ్డుకట్ట పడింది. పరిశుభ్ర జలాల్లో మాత్రమే జీవించే గంగా డాల్ఫిన్ల సంఖ్య రికార్డు స్థాయిలో పెరగడం నది పరిశుభ్రతకు ప్రత్యక్ష నిదర్శనమని శాస్త్రవేత్తలు ప్రకటించారు.",
    "content": "ఉత్తరాఖండ్ నుంచి పశ్చిమ బెంగాల్ వరకు ఏర్పాటు చేసిన 300కు పైగా మురుగునీటి శుద్ధి ప్లాంట్ల వల్ల పారిశ్రామిక వ్యర్థాలు నదిలోకి చేరకుండా అడ్డుకట్ట పడింది. పరిశుభ్ర జలాల్లో మాత్రమే జీవించే గంగా డాల్ఫిన్ల సంఖ్య రికార్డు స్థాయిలో పెరగడం నది పరిశుభ్రతకు ప్రత్యక్ష నిదర్శనమని శాస్త్రవేత్తలు ప్రకటించారు.",
