    "title": "భారత అథ్లెట్ల రికార్డు ప్రదర్శన: అంతర్జాతీయ క్రీడల్లో సరికొత్త పతకాల పంట",
    "subheadline": "షూటింగ్, బ్యాడ్మింటన్, ఆర్చరీ, వెయిట్‌లిఫ్టింగ్‌లో భారత్ ఆధిపత్యం; ఖేలో ఇండియా ప్రతిభ.",
    "slug": "art-te-025-జాతీయం",
    "leadParagraph": "అంతర్జాతీయ క్రీడా వేదికలపై భారత త్రివర్ణ పతాకం సగర్వంగా రెపరెపలాడింది. భారత అథ్లెట్లు రికార్డు స్థాయిలో బంగారు పతకాలను కైవసం చేసుకున్నారు.",
    "summary": "అంతర్జాతీయ క్రీడా వేదికలపై భారత త్రివర్ణ పతాకం సగర్వంగా రెపరెపలాడింది. భారత అథ్లెట్లు రికార్డు స్థాయిలో బంగారు పతకాలను కైవసం చేసుకున్నారు.",
    "synopsis": "అంతర్జాతీయ క్రీడా వేదికలపై భారత త్రివర్ణ పతాకం సగర్వంగా రెపరెపలాడింది. భారత అథ్లెట్లు రికార్డు స్థాయిలో బంగారు పతకాలను కైవసం చేసుకున్నారు.",
    "bodyContent": "కేంద్ర ప్రభుత్వం ప్రవేశపెట్టిన టార్గెట్ ఒలింపిక్ పోడియం స్కీమ్ (TOPS) మరియు ఖేలో ఇండియా గేమ్స్ గ్రామీణ యువతలోని సహజ ప్రతిభను వెలుగులోకి తెచ్చాయి. ప్రపంచ స్థాయి శిక్షణ, పౌష్టికాహారం, విదేశీ కోచ్‌ల మార్గదర్శకత్వంలో మన క్రీడాకారులు ఒలింపిక్స్ లక్ష్యంగా అద్భుత సాధన చేస్తున్నారు.",
