    "summary": "కేంద్ర పట్టణాభివృద్ధి శాఖ ప్రకటించిన జాతీయ స్వచ్ఛ సర్వేక్షణ్ అవార్డుల్లో తెలుగు రాష్ట్రాల నగరాలు ఘన విజయాలు సాధించాయి.",
    "synopsis": "కేంద్ర పట్టణాభివృద్ధి శాఖ ప్రకటించిన జాతీయ స్వచ్ఛ సర్వేక్షణ్ అవార్డుల్లో తెలుగు రాష్ట్రాల నగరాలు ఘన విజయాలు సాధించాయి.",
    "bodyContent": "పట్టణాలలో చెత్త సేకరణ, ప్లాస్టిక్ నియంత్రణ, మురుగునీటి శుద్ధి అంశాలలో విజయవాడ, విశాఖపట్నంలు టాప్ ర్యాంకుల్లో నిలిచాయి. ప్రజల భాగస్వామ్యంతో పారిశుధ్య కార్మికుల అంకితభావం ఈ విజయానికి కారణమని అధికారులు కొనియాడారు.",
    "content": "పట్టణాలలో చెత్త సేకరణ, ప్లాస్టిక్ నియంత్రణ, మురుగునీటి శుద్ధి అంశాలలో విజయవాడ, విశాఖపట్నంలు టాప్ ర్యాంకుల్లో నిలిచాయి. ప్రజల భాగస్వామ్యంతో పారిశుధ్య కార్మికుల అంకితభావం ఈ విజయానికి కారణమని అధికారులు కొనియాడారు.",
