    "headline": "వస్తు ఎగుమతుల్లో నవశకం: 450 బిలియన్ డాలర్ల మార్కును దాటిన భారత వాణిజ్యం",
    "title": "వస్తు ఎగుమతుల్లో నవశకం: 450 బిలియన్ డాలర్ల మార్కును దాటిన భారత వాణిజ్యం",
    "subheadline": "ఇంజనీరింగ్ వస్తువులు, ఫార్మా, ఎలక్ట్రానిక్స్, టెక్స్‌టైల్స్ ఎగుమతుల్లో భారీ డిమాండ్.",
    "slug": "art-te-029-జాతీయం",
    "leadParagraph": "గ్లోబల్ మార్కెట్లలో భారతీయ ఉత్పత్తులకు ఆదరణ రోజురోజుకూ పెరుగుతోంది. దేశ ఎగుమతుల రంగం సరికొత్త రికార్డులను అధిగమించింది.",
    "summary": "గ్లోబల్ మార్కెట్లలో భారతీయ ఉత్పత్తులకు ఆదరణ రోజురోజుకూ పెరుగుతోంది. దేశ ఎగుమతుల రంగం సరికొత్త రికార్డులను అధిగమించింది.",
    "synopsis": "గ్లోబల్ మార్కెట్లలో భారతీయ ఉత్పత్తులకు ఆదరణ రోజురోజుకూ పెరుగుతోంది. దేశ ఎగుమతుల రంగం సరికొత్త రికార్డులను అధిగమించింది.",
    "bodyContent": "అమెరికా, యూరప్, మధ్యప్రాచ్య దేశాలతో వాణిజ్య ఒప్పందాలు కుదుర్చుకోవడంతో మేకిన్ ఇండియా ఉత్పత్తులకు భారీ ఎత్తున ఆర్డర్లు లభిస్తున్నాయి. కంటైనర్ పోర్టులలో వేగవంతమైన కస్టమ్స్ క్లియరెన్స్ వ్యవస్థ ఎగుమతిదారులకు మరింత ఊతమిచ్చింది.",
    "content": "అమెరికా, యూరప్, మధ్యప్రాచ్య దేశాలతో వాణిజ్య ఒప్పందాలు కుదుర్చుకోవడంతో మేకిన్ ఇండియా ఉత్పత్తులకు భారీ ఎత్తున ఆర్డర్లు లభిస్తున్నాయి. కంటైనర్ పోర్టులలో వేగవంతమైన కస్టమ్స్ క్లియరెన్స్ వ్యవస్థ ఎగుమతిదారులకు మరింత ఊతమిచ్చింది.",
