    "tenantId": "tenant-metro-chronicle",
    "headline": "జాతీయ క్రీడా పురస్కారాలు: తెలుగు క్రీడాకారులకు రాష్ట్రపతి చేతుల మీదుగా అర్జున అవార్డులు",
    "title": "జాతీయ క్రీడా పురస్కారాలు: తెలుగు క్రీడాకారులకు రాష్ట్రపతి చేతుల మీదుగా అర్జున అవార్డులు",
    "subheadline": "బ్యాడ్మింటన్, ఆర్చరీ, చెస్ క్రీడల్లో అంతర్జాతీయ పతకాలు సాధించిన క్రీడాకారులకు సత్కారం.",
    "slug": "art-te-030-జాతీయం",
    "leadParagraph": "రాష్ట్రపతి భవన్‌లో జరిగిన వర్ణరంభోత్సవంలో భారత రాష్ట్రపతి క్రీడా రంగంలో విశిష్ట ప్రతిభ కనబరిచిన యువతకు జాతీయ అవార్డులను ప్రదానం చేశారు.",
    "summary": "రాష్ట్రపతి భవన్‌లో జరిగిన వర్ణరంభోత్సవంలో భారత రాష్ట్రపతి క్రీడా రంగంలో విశిష్ట ప్రతిభ కనబరిచిన యువతకు జాతీయ అవార్డులను ప్రదానం చేశారు.",
    "synopsis": "రాష్ట్రపతి భవన్‌లో జరిగిన వర్ణరంభోత్సవంలో భారత రాష్ట్రపతి క్రీడా రంగంలో విశిష్ట ప్రతిభ కనబరిచిన యువతకు జాతీయ అవార్డులను ప్రదానం చేశారు.",
    "bodyContent": "తెలుగు రాష్ట్రాలకు చెందిన యువ ప్రతిభావంతులు ప్రతిష్టాత్మక అర్జున అవార్డులను అందుకున్నారు. ఈ సందర్భంగా రాష్ట్రపతి మాట్లాడుతూ క్రీడలు యువతలో క్రమశిక్షణ, దేశభక్తిని పెంపొందిస్తాయని, వారి సాధన రాబోయే తరాలకు స్ఫూర్తిదాయకమని కొనియాడారు.",
    "content": "తెలుగు రాష్ట్రాలకు చెందిన యువ ప్రతిభావంతులు ప్రతిష్టాత్మక అర్జున అవార్డులను అందుకున్నారు. ఈ సందర్భంగా రాష్ట్రపతి మాట్లాడుతూ క్రీడలు యువతలో క్రమశిక్షణ, దేశభక్తిని పెంపొందిస్తాయని, వారి సాధన రాబోయే తరాలకు స్ఫూర్తిదాయకమని కొనియాడారు.",
