    "tenantId": "tenant-metro-chronicle",
    "headline": "పోలవరం జాతీయ ప్రాజెక్టు కొత్త డయాఫ్రమ్ వాల్ నిర్మాణం ప్రారంభం: కేంద్రం పూర్తి నిధులు విడుదల",
    "title": "పోలవరం జాతీయ ప్రాజెక్టు కొత్త డయాఫ్రమ్ వాల్ నిర్మాణం ప్రారంభం: కేంద్రం పూర్తి నిధులు విడుదల",
    "subheadline": "గోదావరి వరదలను తట్టుకునేలా అత్యంత పటిష్ట సాంకేతికత; 2026 నాటికి గ్రావిటీ ద్వారా సాగునీరు.",
    "slug": "art-te-032-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్ రాష్ట్ర జీవనాడి పోలవరం ప్రాజెక్టు కీలక ఘట్టానికి చేరుకుంది. గతంలో దెబ్బతిన్న డయాఫ్రమ్ వాల్ స్థానంలో సరికొత్త డయాఫ్రమ్ వాల్ నిర్మాణాన్ని అంతర్జాతీయ నిపుణుల సమక్షంలో ప్రారంభించారు.",
    "summary": "ఆంధ్రప్రదేశ్ రాష్ట్ర జీవనాడి పోలవరం ప్రాజెక్టు కీలక ఘట్టానికి చేరుకుంది. గతంలో దెబ్బతిన్న డయాఫ్రమ్ వాల్ స్థానంలో సరికొత్త డయాఫ్రమ్ వాల్ నిర్మాణాన్ని అంతర్జాతీయ నిపుణుల సమక్షంలో ప్రారంభించారు.",
    "synopsis": "ఆంధ్రప్రదేశ్ రాష్ట్ర జీవనాడి పోలవరం ప్రాజెక్టు కీలక ఘట్టానికి చేరుకుంది. గతంలో దెబ్బతిన్న డయాఫ్రమ్ వాల్ స్థానంలో సరికొత్త డయాఫ్రమ్ వాల్ నిర్మాణాన్ని అంతర్జాతీయ నిపుణుల సమక్షంలో ప్రారంభించారు.",
    "bodyContent": "కేంద్ర జలసంఘం నిపుణులు, కెనడా మరియు జర్మనీ ఇంజనీర్ల పర్యవేక్షణలో అత్యాధునిక హైడ్రాలిక్ కట్టర్లను రంగంలోకి దించారు. పోలవరం పూర్తి కావడం ద్వారా ఉభయ గోదావరి, ఉత్తరాంధ్ర, రాయలసీమ ప్రాంతాలకు తాగునీరు మరియు సాగునీరు పుష్కలంగా అందుతుంది. సహాయ పునరావాస (R&R) ప్యాకేజీని పారదర్శకంగా పంపిణీ చేస్తున్నారు.",
    "content": "కేంద్ర జలసంఘం నిపుణులు, కెనడా మరియు జర్మనీ ఇంజనీర్ల పర్యవేక్షణలో అత్యాధునిక హైడ్రాలిక్ కట్టర్లను రంగంలోకి దించారు. పోలవరం పూర్తి కావడం ద్వారా ఉభయ గోదావరి, ఉత్తరాంధ్ర, రాయలసీమ ప్రాంతాలకు తాగునీరు మరియు సాగునీరు పుష్కలంగా అందుతుంది. సహాయ పునరావాస (R&R) ప్యాకేజీని పారదర్శకంగా పంపిణీ చేస్తున్నారు.",
