    "title": "విశాఖపట్నం మెట్రో ప్రాజెక్టుకు కేంద్ర ఆమోద ముద్ర: 76 కిలోమీటర్ల కారిడార్లకు నిధులు",
    "subheadline": "గాజువాక నుంచి భోగాపురం ఇంటర్నేషనల్ ఎయిర్‌పోర్టు వరకు రాపిడ్ మెట్రో సర్వీసులు.",
    "slug": "art-te-034-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్ ఆర్థిక రాజధాని విశాఖ నగర రవాణా ముఖచిత్రం మారనుంది. విశాఖ మెట్రో ప్రాజెక్టు డిటైల్డ్ ప్రాజెక్ట్ రిపోర్ట్ (డీపీఆర్) కు కేంద్ర పట్టణాభివృద్ధి శాఖ గ్రీన్ సిగ్నల్ ఇచ్చింది.",
    "summary": "ఆంధ్రప్రదేశ్ ఆర్థిక రాజధాని విశాఖ నగర రవాణా ముఖచిత్రం మారనుంది. విశాఖ మెట్రో ప్రాజెక్టు డిటైల్డ్ ప్రాజెక్ట్ రిపోర్ట్ (డీపీఆర్) కు కేంద్ర పట్టణాభివృద్ధి శాఖ గ్రీన్ సిగ్నల్ ఇచ్చింది.",
    "synopsis": "ఆంధ్రప్రదేశ్ ఆర్థిక రాజధాని విశాఖ నగర రవాణా ముఖచిత్రం మారనుంది. విశాఖ మెట్రో ప్రాజెక్టు డిటైల్డ్ ప్రాజెక్ట్ రిపోర్ట్ (డీపీఆర్) కు కేంద్ర పట్టణాభివృద్ధి శాఖ గ్రీన్ సిగ్నల్ ఇచ్చింది.",
    "bodyContent": "తొలి విడతగా కొమ్మాది నుంచి గాజువాక మరియు ఎన్‌ఏడీ జంక్షన్ నుంచి భోగాపురం గ్రీన్‌ఫీల్డ్ విమానాశ్రయం వరకు మెట్రో లైన్లు నిర్మించనున్నారు. పర్యాటక రంగంతో పాటు ఐటీ ఉద్యోగులకు, పారిశ్రామిక కార్మికులకు ఈ మెట్రో గొప్ప రవాణా సాధనం కానుంది. పర్యావరణహిత ఎలక్ట్రిక్ కోచ్‌లతో నగరంలో కాలుష్యం భారీగా తగ్గనుంది.",
    "content": "తొలి విడతగా కొమ్మాది నుంచి గాజువాక మరియు ఎన్‌ఏడీ జంక్షన్ నుంచి భోగాపురం గ్రీన్‌ఫీల్డ్ విమానాశ్రయం వరకు మెట్రో లైన్లు నిర్మించనున్నారు. పర్యాటక రంగంతో పాటు ఐటీ ఉద్యోగులకు, పారిశ్రామిక కార్మికులకు ఈ మెట్రో గొప్ప రవాణా సాధనం కానుంది. పర్యావరణహిత ఎలక్ట్రిక్ కోచ్‌లతో నగరంలో కాలుష్యం భారీగా తగ్గనుంది.",
