    "headline": "హైదరాబాద్‌లో గ్లోబల్ ఏఐ సిటీ ఏర్పాటుకు ఒప్పందాలు: రూ. 10,000 కోట్ల పెట్టుబడులు",
    "title": "హైదరాబాద్‌లో గ్లోబల్ ఏఐ సిటీ ఏర్పాటుకు ఒప్పందాలు: రూ. 10,000 కోట్ల పెట్టుబడులు",
    "subheadline": "ముచ్చింతల్ పరిసరాల్లో 200 ఎకరాల్లో ఆర్టిఫిషియల్ ఇంటెలిజెన్స్ హబ్; గ్లోబల్ టెక్ దిగ్గజాల భాగస్వామ్యం.",
    "slug": "art-te-035-రాష్ట్రీయం",
    "leadParagraph": "భారతదేశాన్ని గ్లోబల్ ఆర్టిఫిషియల్ ఇంటెలిజెన్స్ రాజధానిగా నిలిపేందుకు తెలంగాణ ప్రభుత్వం హైదరాబాద్ శివార్లలో అంతర్జాతీయ ఏఐ సిటీ ప్రాజెక్టుకు భూమిపూజ చేసింది.",
    "summary": "భారతదేశాన్ని గ్లోబల్ ఆర్టిఫిషియల్ ఇంటెలిజెన్స్ రాజధానిగా నిలిపేందుకు తెలంగాణ ప్రభుత్వం హైదరాబాద్ శివార్లలో అంతర్జాతీయ ఏఐ సిటీ ప్రాజెక్టుకు భూమిపూజ చేసింది.",
    "synopsis": "భారతదేశాన్ని గ్లోబల్ ఆర్టిఫిషియల్ ఇంటెలిజెన్స్ రాజధానిగా నిలిపేందుకు తెలంగాణ ప్రభుత్వం హైదరాబాద్ శివార్లలో అంతర్జాతీయ ఏఐ సిటీ ప్రాజెక్టుకు భూమిపూజ చేసింది.",
    "bodyContent": "ప్రపంచ ప్రఖ్యాత టెక్ దిగ్గజాలైన మైక్రోసాఫ్ట్, గూగుల్, ఎన్విడియా ప్రతినిధులు ఈ ప్రాజెక్టులో రీసెర్చ్ ల్యాబ్‌లను నెలకొల్పేందుకు అంగీకారం కుదుర్చుకున్నారు. హెల్త్‌కేర్, అగ్రికల్చర్, ఆటోమేషన్ రంగాల్లో ఏఐ ఆధారిత ఆవిష్కరణలను ప్రోత్సహించడం దీని ముఖ్య ఉద్దేశ్యం. దీనిద్వారా రాబోయే ఐదేళ్లలో లక్ష మందికి పైగా నిపుణులకు ప్రత్యక్ష ఉపాధి దక్కనుంది.",
    "content": "ప్రపంచ ప్రఖ్యాత టెక్ దిగ్గజాలైన మైక్రోసాఫ్ట్, గూగుల్, ఎన్విడియా ప్రతినిధులు ఈ ప్రాజెక్టులో రీసెర్చ్ ల్యాబ్‌లను నెలకొల్పేందుకు అంగీకారం కుదుర్చుకున్నారు. హెల్త్‌కేర్, అగ్రికల్చర్, ఆటోమేషన్ రంగాల్లో ఏఐ ఆధారిత ఆవిష్కరణలను ప్రోత్సహించడం దీని ముఖ్య ఉద్దేశ్యం. దీనిద్వారా రాబోయే ఐదేళ్లలో లక్ష మందికి పైగా నిపుణులకు ప్రత్యక్ష ఉపాధి దక్కనుంది.",
