    "title": "ఆంధ్రప్రదేశ్‌లో దీపం-2 పథకం ప్రారంభం: అర్హులైన మహిళలకు ఏడాదికి 3 ఉచిత గ్యాస్ సిలిండర్లు",
    "subheadline": "దీపావళి కానుకగా రాష్ట్రవ్యాప్తంగా పథకం అమలు; మహిళల సాధికారతకు ప్రభుత్వం పెద్దపీట.",
    "slug": "art-te-036-రాష్ట్రీయం",
    "leadParagraph": "ఎన్నికల హామీల్లో భాగంగా ఇచ్చిన సూపర్-సిక్స్ హామీని నెరవేరుస్తూ పేద మహిళల కోసం ఉచిత గ్యాస్ సిలిండర్ల పథకాన్ని ఆంధ్రప్రదేశ్ ముఖ్యమంత్రి ఘనంగా ప్రారంభించారు.",
    "summary": "ఎన్నికల హామీల్లో భాగంగా ఇచ్చిన సూపర్-సిక్స్ హామీని నెరవేరుస్తూ పేద మహిళల కోసం ఉచిత గ్యాస్ సిలిండర్ల పథకాన్ని ఆంధ్రప్రదేశ్ ముఖ్యమంత్రి ఘనంగా ప్రారంభించారు.",
    "synopsis": "ఎన్నికల హామీల్లో భాగంగా ఇచ్చిన సూపర్-సిక్స్ హామీని నెరవేరుస్తూ పేద మహిళల కోసం ఉచిత గ్యాస్ సిలిండర్ల పథకాన్ని ఆంధ్రప్రదేశ్ ముఖ్యమంత్రి ఘనంగా ప్రారంభించారు.",
    "bodyContent": "రాష్ట్రవ్యాప్తంగా దాదాపు ఒక కోటి ఇరవై లక్షల మంది మహిళలకు ఈ పథకం ద్వారా లబ్ధి చేకూరనుంది. గ్యాస్ బుక్ చేసుకున్న 48 గంటల్లోనే సబ్సిడీ సొమ్ము లబ్ధిదారురాలి బ్యాంక్ ఖాతాలో జమ అయ్యేలా ఆధునిక సాంకేతిక వ్యవస్థను సిద్ధం చేశారు. గ్రామీణ ప్రాంతాల్లో పొగ రహిత వంటగదుల సాధనకు ఇది మహోన్నత చర్యగా గుర్తింపు పొందింది.",
    "content": "రాష్ట్రవ్యాప్తంగా దాదాపు ఒక కోటి ఇరవై లక్షల మంది మహిళలకు ఈ పథకం ద్వారా లబ్ధి చేకూరనుంది. గ్యాస్ బుక్ చేసుకున్న 48 గంటల్లోనే సబ్సిడీ సొమ్ము లబ్ధిదారురాలి బ్యాంక్ ఖాతాలో జమ అయ్యేలా ఆధునిక సాంకేతిక వ్యవస్థను సిద్ధం చేశారు. గ్రామీణ ప్రాంతాల్లో పొగ రహిత వంటగదుల సాధనకు ఇది మహోన్నత చర్యగా గుర్తింపు పొందింది.",
