    "title": "కాళేశ్వరం ప్రాజెక్టు మేడిగడ్డ బ్యారేజీ తాత్కాలిక పునరుద్ధరణ పూర్తి: నిపుణుల కమిటీ పర్యవేక్షణ",
    "subheadline": "ఎన్‌డీఎస్‌ఏ సిఫారసులకు అనుగుణంగా మరమ్మతులు; సాగునీటి పంపింగ్‌పై ప్రభుత్వం సమగ్ర సమీక్ష.",
