    "title": "ఆర్టీసీ బస్సుల్లో మహిళలకు ఉచిత ప్రయాణం: రెండు రాష్ట్రాల్లో రికార్డు స్పందన",
    "subheadline": "విద్యార్థినులు, చిరువ్యాపార మహిళలకు ఆర్థిక వెసులుబాటు; నూతనంగా 2000 ఎలక్ట్రిక్ బస్సుల కొనుగోలు.",
    "slug": "art-te-038-రాష్ట్రీయం",
    "leadParagraph": "ప్రజా రవాణా వ్యవస్థలో మహిళా సాధికారతే లక్ష్యంగా ప్రవేశపెట్టిన ఆర్టీసీ ఉచిత ప్రయాణ పథకం తెలుగు రాష్ట్రాలలో అద్భుత ప్రజాదరణ పొందుతోంది.",
    "summary": "ప్రజా రవాణా వ్యవస్థలో మహిళా సాధికారతే లక్ష్యంగా ప్రవేశపెట్టిన ఆర్టీసీ ఉచిత ప్రయాణ పథకం తెలుగు రాష్ట్రాలలో అద్భుత ప్రజాదరణ పొందుతోంది.",
    "synopsis": "ప్రజా రవాణా వ్యవస్థలో మహిళా సాధికారతే లక్ష్యంగా ప్రవేశపెట్టిన ఆర్టీసీ ఉచిత ప్రయాణ పథకం తెలుగు రాష్ట్రాలలో అద్భుత ప్రజాదరణ పొందుతోంది.",
    "bodyContent": "ఉచిత ప్రయాణం ప్రారంభమైన నాటి నుంచి ఆర్టీసీ బస్సులలో రద్దీ గణనీయంగా పెరిగింది. ప్రయాణికుల సౌకర్యార్థం అదనపు సర్వీసులు నడపడంతో పాటు సరికొత్త పర్యావరణహిత ఎలక్ట్రిక్ బస్సులను డిపోలకు కేటాయిస్తున్నారు. మహిళలు స్వయం ఉపాధి కోసం ప్రయాణ ఖర్చులు ఆదా చేసుకోవడం వారి కుటుంబాలకు ఆసరాగా నిలిచింది.",
    "content": "ఉచిత ప్రయాణం ప్రారంభమైన నాటి నుంచి ఆర్టీసీ బస్సులలో రద్దీ గణనీయంగా పెరిగింది. ప్రయాణికుల సౌకర్యార్థం అదనపు సర్వీసులు నడపడంతో పాటు సరికొత్త పర్యావరణహిత ఎలక్ట్రిక్ బస్సులను డిపోలకు కేటాయిస్తున్నారు. మహిళలు స్వయం ఉపాధి కోసం ప్రయాణ ఖర్చులు ఆదా చేసుకోవడం వారి కుటుంబాలకు ఆసరాగా నిలిచింది.",
