    "subheadline": "రాష్ట్ర యువతకు భవిష్యత్ సాంకేతిక పరిజ్ఞానంలో ఉచిత శిక్షణ; గ్లోబల్ ప్రాజెక్టులకు ఆంధ్రప్రదేశ్ వేదిక.",
    "slug": "art-te-039-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్ నవ్యాంధ్ర రాజధానిని హైటెక్ నాలెడ్జ్ హబ్‌గా తీర్చిదిద్దే బృహత్ ప్రణాళికలో భాగంగా క్వాంటమ్ కంప్యూటింగ్ సెంటర్ ఆఫ్ ఎక్సలెన్స్ ఏర్పాటవుతోంది.",
    "summary": "ఆంధ్రప్రదేశ్ నవ్యాంధ్ర రాజధానిని హైటెక్ నాలెడ్జ్ హబ్‌గా తీర్చిదిద్దే బృహత్ ప్రణాళికలో భాగంగా క్వాంటమ్ కంప్యూటింగ్ సెంటర్ ఆఫ్ ఎక్సలెన్స్ ఏర్పాటవుతోంది.",
    "synopsis": "ఆంధ్రప్రదేశ్ నవ్యాంధ్ర రాజధానిని హైటెక్ నాలెడ్జ్ హబ్‌గా తీర్చిదిద్దే బృహత్ ప్రణాళికలో భాగంగా క్వాంటమ్ కంప్యూటింగ్ సెంటర్ ఆఫ్ ఎక్సలెన్స్ ఏర్పాటవుతోంది.",
    "bodyContent": "టాటా కన్సల్టెన్సీ సర్వీసెస్ (TCS) మరియు ఐబీఎం సంయుక్తంగా ఈ నాలెడ్జ్ క్యాంపస్‌ను నిర్మించనున్నాయి. ఏటా 15,000 మంది ఇంజనీరింగ్ గ్రాడ్యుయేట్లకు క్వాంటమ్ ఆల్గారిథమ్స్, సైబర్ సెక్యూరిటీలలో అత్యున్నత శిక్షణ ఇచ్చి గ్లోబల్ ఉద్యోగ అవకాశాలు కల్పించనున్నారు.",
    "content": "టాటా కన్సల్టెన్సీ సర్వీసెస్ (TCS) మరియు ఐబీఎం సంయుక్తంగా ఈ నాలెడ్జ్ క్యాంపస్‌ను నిర్మించనున్నాయి. ఏటా 15,000 మంది ఇంజనీరింగ్ గ్రాడ్యుయేట్లకు క్వాంటమ్ ఆల్గారిథమ్స్, సైబర్ సెక్యూరిటీలలో అత్యున్నత శిక్షణ ఇచ్చి గ్లోబల్ ఉద్యోగ అవకాశాలు కల్పించనున్నారు.",
