    "tenantId": "tenant-metro-chronicle",
    "headline": "తెలంగాణ గ్రామ పంచాయతీలకు రూ. 1200 కోట్ల నిధుల విడుదల: పల్లెల్లో శరవేగంగా అభివృద్ధి పనులు",
    "title": "తెలంగాణ గ్రామ పంచాయతీలకు రూ. 1200 కోట్ల నిధుల విడుదల: పల్లెల్లో శరవేగంగా అభివృద్ధి పనులు",
    "subheadline": "గ్రామాల్లో పక్కా సీసీ రోడ్లు, వైకుంఠ ధామాలు, తాగునీటి శుద్ధి కేంద్రాల నిర్వహణకు ప్రత్యేక ప్రాధాన్యం.",
    "slug": "art-te-040-రాష్ట్రీయం",
    "leadParagraph": "తెలంగాణలోని గ్రామ పంచాయతీలకు పెండింగ్ నిధులను రాష్ట్ర ప్రభుత్వం తక్షణమే విడుదల చేసింది. గ్రామీణ స్వయం పాలనకు నూతన ఊపిరి లభించింది.",
    "summary": "తెలంగాణలోని గ్రామ పంచాయతీలకు పెండింగ్ నిధులను రాష్ట్ర ప్రభుత్వం తక్షణమే విడుదల చేసింది. గ్రామీణ స్వయం పాలనకు నూతన ఊపిరి లభించింది.",
    "synopsis": "తెలంగాణలోని గ్రామ పంచాయతీలకు పెండింగ్ నిధులను రాష్ట్ర ప్రభుత్వం తక్షణమే విడుదల చేసింది. గ్రామీణ స్వయం పాలనకు నూతన ఊపిరి లభించింది.",
    "bodyContent": "కేంద్ర ఆర్థిక సంఘం నిధులతో పాటు రాష్ట్ర నిధులను కలిపి నేరుగా పంచాయతీ అకౌంట్లలో జమ చేశారు. పల్లెల్లో తాగునీటి సరఫరా, వీధి దీపాల నిర్వహణ, పారిశుద్ధ్య పనులకు నిధుల కొరత లేకుండా చర్యలు చేపట్టారు. సర్పంచుల సమన్వయంతో గ్రామ సభలు నిర్వహించి ప్రాధాన్యతా పనులను ప్రారంభించారు.",
    "content": "కేంద్ర ఆర్థిక సంఘం నిధులతో పాటు రాష్ట్ర నిధులను కలిపి నేరుగా పంచాయతీ అకౌంట్లలో జమ చేశారు. పల్లెల్లో తాగునీటి సరఫరా, వీధి దీపాల నిర్వహణ, పారిశుద్ధ్య పనులకు నిధుల కొరత లేకుండా చర్యలు చేపట్టారు. సర్పంచుల సమన్వయంతో గ్రామ సభలు నిర్వహించి ప్రాధాన్యతా పనులను ప్రారంభించారు.",
