    "headline": "ఏపీ నూతన పారిశ్రామిక విధానం 4.0: రూ. 50,000 కోట్ల పెట్టుబడులకు కేబినెట్ ఆమోదం",
    "title": "ఏపీ నూతన పారిశ్రామిక విధానం 4.0: రూ. 50,000 కోట్ల పెట్టుబడులకు కేబినెట్ ఆమోదం",
    "subheadline": "సింగిల్ విండో ద్వారా 21 రోజుల్లోనే పరిశ్రమలకు అనుమతులు; గ్రీన్ ఎనర్జీ, ఈవీ రంగాలకు భారీ ప్రోత్సాహకాలు.",
    "slug": "art-te-041-రాష్ట్రీయం",
    "leadParagraph": "రాష్ట్రంలో పారిశ్రామిక విప్లవానికి బాటలు వేస్తూ ఆంధ్రప్రదేశ్ ప్రభుత్వం సరికొత్త పారిశ్రామిక పాలసీకి చట్టబద్ధత కల్పించింది.",
    "summary": "రాష్ట్రంలో పారిశ్రామిక విప్లవానికి బాటలు వేస్తూ ఆంధ్రప్రదేశ్ ప్రభుత్వం సరికొత్త పారిశ్రామిక పాలసీకి చట్టబద్ధత కల్పించింది.",
    "synopsis": "రాష్ట్రంలో పారిశ్రామిక విప్లవానికి బాటలు వేస్తూ ఆంధ్రప్రదేశ్ ప్రభుత్వం సరికొత్త పారిశ్రామిక పాలసీకి చట్టబద్ధత కల్పించింది.",
    "bodyContent": "పారిశ్రామికవేత్తలకు భూముల కేటాయింపు, విద్యుత్ రాయితీలు, పన్ను మినహాయింపులను పారదర్శకంగా ఆన్‌లైన్ ద్వారా అందించనున్నారు. ముఖ్యంగా ఎలక్ట్రానిక్స్ తయారీ, గ్రీన్ హైడ్రోజన్, ఫార్మా రంగాల్లో భారీ పరిశ్రమలు తరలివస్తున్నాయి. స్థానిక యువతకు 70 శాతం ఉద్యోగాలు కల్పించే నిబంధనను పటిష్టంగా అమలు చేయనున్నారు.",
