    "title": "మూసీ రివర్‌ఫ్రంట్ పునరుజ్జీవన ప్రాజెక్టు: హైదరాబాద్ చారిత్రక నదికి సరికొత్త జీవకళ",
    "subheadline": "వరల్డ్ క్లాస్ వాక్‌వేలు, వాటర్ ఫ్రంట్ పార్కులు, చెక్ డ్యామ్‌ల నిర్మాణానికి మాస్టర్ ప్లాన్ సిద్ధం.",
