    "title": "ఆంధ్రప్రదేశ్ వ్యాప్తంగా ఉచిత ఇసుక విధానం పకడ్బందీ అమలు: భవన నిర్మాణ రంగానికి ఊరట",
    "subheadline": "రీచ్‌ల వద్ద సీసీ కెమెరాల నిఘా; కేవలం రవాణా చార్జీలకే ప్రజలకు ఇసుక లభ్యత.",
    "slug": "art-te-043-రాష్ట్రీయం",
