    "summary": "సామాన్యుల ఇంటి నిర్మాణ కలలను సులభతరం చేసేందుకు ఆంధ్రప్రదేశ్ ప్రభుత్వం అమల్లోకి తెచ్చిన ఉచిత ఇసుక విధానం విజయవంతంగా సాగుతోంది.",
    "synopsis": "సామాన్యుల ఇంటి నిర్మాణ కలలను సులభతరం చేసేందుకు ఆంధ్రప్రదేశ్ ప్రభుత్వం అమల్లోకి తెచ్చిన ఉచిత ఇసుక విధానం విజయవంతంగా సాగుతోంది.",
    "bodyContent": "నదీ తీరాల్లోని ఇసుక రీచ్‌ల నుంచి మధ్యవర్తులు, అక్రమ రవాణాదారులను పూర్తిగా కట్టడి చేశారు. ప్రజలు నేరుగా ట్రాక్టర్లు, లారీల ద్వారా నిర్దేశిత సీనరేజ్ రుసుము చెల్లించి ఇసుకను తరలించుకునే సౌలభ్యం కల్పించారు. దీనివల్ల రాష్ట్రవ్యాప్తంగా నిలిచిపోయిన ప్రైవేట్, ప్రభుత్వ భవన నిర్మాణ పనులు మళ్లీ వేగం పుంజుకున్నాయి.",
