    "headline": "కృష్ణా, గోదావరి నదీ జలాల అపెక్స్ కౌన్సిల్ భేటీ: ప్రాజెక్టులకు సమగ్ర నీటి కేటాయింపులపై ఏకాభిప్రాయం",
    "title": "కృష్ణా, గోదావరి నదీ జలాల అపెక్స్ కౌన్సిల్ భేటీ: ప్రాజెక్టులకు సమగ్ర నీటి కేటాయింపులపై ఏకాభిప్రాయం",
    "subheadline": "రెండు రాష్ట్రాల రైతుల ప్రయోజనాలే పరమావధి; రియల్ టైమ్ టెలిమెట్రీ పరికరాల అమరికకు నిర్ణయం.",
    "slug": "art-te-045-రాష్ట్రీయం",
    "leadParagraph": "తెలుగు రాష్ట్రాల మధ్య నదీ జలాల సమర్థ నిర్వహణపై కేంద్ర జలశక్తి మంత్రిత్వ శాఖ ఆధ్వర్యంలో ఉన్నతస్థాయి సమావేశం సౌహార్దపూర్వక వాతావరణంలో జరిగింది.",
    "summary": "తెలుగు రాష్ట్రాల మధ్య నదీ జలాల సమర్థ నిర్వహణపై కేంద్ర జలశక్తి మంత్రిత్వ శాఖ ఆధ్వర్యంలో ఉన్నతస్థాయి సమావేశం సౌహార్దపూర్వక వాతావరణంలో జరిగింది.",
    "synopsis": "తెలుగు రాష్ట్రాల మధ్య నదీ జలాల సమర్థ నిర్వహణపై కేంద్ర జలశక్తి మంత్రిత్వ శాఖ ఆధ్వర్యంలో ఉన్నతస్థాయి సమావేశం సౌహార్దపూర్వక వాతావరణంలో జరిగింది.",
    "bodyContent": "గోదావరి వరద జలాలను సమర్థవంతంగా వినియోగించుకోవడం, కృష్ణా డెల్టా మరియు నాగార్జునసాగర్ ఆయకట్టుకు సకాలంలో నీటిని విడుదల చేయడంపై ఇరు రాష్ట్రాల అధికారులు రోడ్‌మ్యాప్ రూపొందించారు. నదీ ప్రాజెక్టుల వద్ద వివాదరహితంగా ఆటోమేటిక్ గేట్ రీడింగ్ యంత్రాలను ఏర్పాటు చేయనున్నారు.",
    "content": "గోదావరి వరద జలాలను సమర్థవంతంగా వినియోగించుకోవడం, కృష్ణా డెల్టా మరియు నాగార్జునసాగర్ ఆయకట్టుకు సకాలంలో నీటిని విడుదల చేయడంపై ఇరు రాష్ట్రాల అధికారులు రోడ్‌మ్యాప్ రూపొందించారు. నదీ ప్రాజెక్టుల వద్ద వివాదరహితంగా ఆటోమేటిక్ గేట్ రీడింగ్ యంత్రాలను ఏర్పాటు చేయనున్నారు.",
