    "title": "రాష్ట్రవ్యాప్తంగా నూతన పాఠశాల భవనాలు, డిజిటల్ సైన్స్ ల్యాబ్‌ల ప్రారంభోత్సవం",
    "subheadline": "ప్రభుత్వ బడులలో ఇంగ్లీష్ మీడియంతో పాటు మాతృభాష ప్రావీణ్యతకు సమతూకం; విద్యార్థులకు ట్యాబ్‌లు పంపిణీ.",
