    "headline": "జీనోమ్ వ్యాలీలో లైఫ్ సైన్సెస్ భారీ విస్తరణ: ప్రపంచ ఫార్మా హబ్‌గా హైదరాబాద్ ప్రస్థానం",
    "title": "జీనోమ్ వ్యాలీలో లైఫ్ సైన్సెస్ భారీ విస్తరణ: ప్రపంచ ఫార్మా హబ్‌గా హైదరాబాద్ ప్రస్థానం",
    "subheadline": "రూ. 4000 కోట్ల విస్తరణ పనులకు ఒప్పందాలు; అంటువ్యాధుల వ్యాక్సిన్ల తయారీలో రికార్డు.",
    "slug": "art-te-047-రాష్ట్రీయం",
    "leadParagraph": "ప్రపంచంలో ఉత్పత్తి అయ్యే వ్యాక్సిన్లలో ప్రతి మూడు మోతాదుల్లో ఒకటి హైదరాబాద్ జీనోమ్ వ్యాలీ నుంచే వస్తోందని అంతర్జాతీయ హెల్త్‌కేర్ సమ్మిట్ కొనియాడింది.",
    "summary": "ప్రపంచంలో ఉత్పత్తి అయ్యే వ్యాక్సిన్లలో ప్రతి మూడు మోతాదుల్లో ఒకటి హైదరాబాద్ జీనోమ్ వ్యాలీ నుంచే వస్తోందని అంతర్జాతీయ హెల్త్‌కేర్ సమ్మిట్ కొనియాడింది.",
    "synopsis": "ప్రపంచంలో ఉత్పత్తి అయ్యే వ్యాక్సిన్లలో ప్రతి మూడు మోతాదుల్లో ఒకటి హైదరాబాద్ జీనోమ్ వ్యాలీ నుంచే వస్తోందని అంతర్జాతీయ హెల్త్‌కేర్ సమ్మిట్ కొనియాడింది.",
    "bodyContent": "బయోటెక్నాలజీ, క్లినికల్ రీసెర్చ్ విభాగాల్లో నూతన పరిశోధన కేంద్రాల స్థాపనకు యూరప్, అమెరికా ఫార్మా సంస్థలు ముందుకు వచ్చాయి. బయో-ఫార్మా పార్కులకు నాణ్యమైన ముడిసరుకులు, పరిశోధనా వాతావరణం కల్పించడంలో తెలంగాణ ఆదర్శంగా నిలిచింది.",
    "content": "బయోటెక్నాలజీ, క్లినికల్ రీసెర్చ్ విభాగాల్లో నూతన పరిశోధన కేంద్రాల స్థాపనకు యూరప్, అమెరికా ఫార్మా సంస్థలు ముందుకు వచ్చాయి. బయో-ఫార్మా పార్కులకు నాణ్యమైన ముడిసరుకులు, పరిశోధనా వాతావరణం కల్పించడంలో తెలంగాణ ఆదర్శంగా నిలిచింది.",
