    "title": "ఆంధ్రప్రదేశ్ సముద్ర తీరంలో అత్యాధునిక ఫిషింగ్ హార్బర్ల నిర్మాణం: మత్స్యకారుల సంక్షేమం",
    "subheadline": "సముద్రంలో వేటకు వెళ్లే జాలర్లకు జీపీఎస్ శాటిలైట్ పరికరాలు, కోల్డ్ స్టోరేజ్ సౌకర్యాలు లభ్యం.",
    "slug": "art-te-048-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్‌లోని 974 కిలోమీటర్ల సుదీర్ఘ తీరప్రాంతాన్ని సద్వినియోగం చేసుకుంటూ మత్స్యకారుల ఆర్థిక ప్రగతి కోసం నాలుగు ప్రధాన ఫిషింగ్ హార్బర్లు సిద్ధమయ్యాయి.",
