    "synopsis": "ఆంధ్రప్రదేశ్‌లోని 974 కిలోమీటర్ల సుదీర్ఘ తీరప్రాంతాన్ని సద్వినియోగం చేసుకుంటూ మత్స్యకారుల ఆర్థిక ప్రగతి కోసం నాలుగు ప్రధాన ఫిషింగ్ హార్బర్లు సిద్ధమయ్యాయి.",
    "bodyContent": "బోట్ల రాకపోకలకు సురక్షితమైన జెట్టీలు, చేపలు పాడవకుండా ఐస్ ప్లాంట్లు, వేలంపాట షెడ్లను నిర్మించారు. తుపాను హెచ్చరికలను నేరుగా పడవలలోని వైర్‌లెస్ సెట్లకు పంపే శాటిలైట్ వ్యవస్థను మత్స్యశాఖ అనుసంధానించింది.",
