    "title": "సింగరేణి బొగ్గు గనుల్లో పర్యావరణహిత విప్లవం: 500 మెగావాట్ల సోలార్ ప్లాంట్లు పూర్తి",
    "subheadline": "బొగ్గు ఉత్పత్తితో పాటు గ్రీన్ ఎనర్జీలో అగ్రగామిగా సింగరేణి కాలరీస్ కంపెనీ లిమిటెడ్ (SCCL).",
    "slug": "art-te-049-రాష్ట్రీయం",
    "leadParagraph": "దక్షిణ భారత విద్యుత్ రంగానికి వెన్నెముకైన సింగరేణి సంస్థ కర్బన ఉద్గారాల తగ్గింపులో ముందంజ వేస్తూ భారీ సౌర విద్యుత్ ప్రాజెక్టులను అందుబాటులోకి తెచ్చింది.",
    "summary": "దక్షిణ భారత విద్యుత్ రంగానికి వెన్నెముకైన సింగరేణి సంస్థ కర్బన ఉద్గారాల తగ్గింపులో ముందంజ వేస్తూ భారీ సౌర విద్యుత్ ప్రాజెక్టులను అందుబాటులోకి తెచ్చింది.",
    "synopsis": "దక్షిణ భారత విద్యుత్ రంగానికి వెన్నెముకైన సింగరేణి సంస్థ కర్బన ఉద్గారాల తగ్గింపులో ముందంజ వేస్తూ భారీ సౌర విద్యుత్ ప్రాజెక్టులను అందుబాటులోకి తెచ్చింది.",
    "bodyContent": "గనుల తవ్వకం పూర్తయిన ఖాళీ భూములలో భారీ సోలార్ ప్యానెల్ క్లస్టర్లను ఏర్పాటు చేశారు. సంస్థ సొంత అవసరాలకు సరిపడా విద్యుత్‌ను స్వయంగా ఉత్పత్తి చేసుకోవడమే కాక, మిగులు విద్యుత్‌ను రాష్ట్ర గ్రిడ్‌కు సరఫరా చేయడం ద్వారా సంస్థ లాభాల్లో సరికొత్త రికార్డులను నెలకొల్పింది.",
    "content": "గనుల తవ్వకం పూర్తయిన ఖాళీ భూములలో భారీ సోలార్ ప్యానెల్ క్లస్టర్లను ఏర్పాటు చేశారు. సంస్థ సొంత అవసరాలకు సరిపడా విద్యుత్‌ను స్వయంగా ఉత్పత్తి చేసుకోవడమే కాక, మిగులు విద్యుత్‌ను రాష్ట్ర గ్రిడ్‌కు సరఫరా చేయడం ద్వారా సంస్థ లాభాల్లో సరికొత్త రికార్డులను నెలకొల్పింది.",
