    "title": "ఆంధ్రప్రదేశ్‌లో గుంతల రహిత రహదారుల మిషన్: రూ. 2500 కోట్లతో రీకార్పెటింగ్ పనులు",
    "subheadline": "పంచాయతీ రాజ్, ఆర్ అండ్ బీ రోడ్లకు మహర్దశ; అధునాతన మ్యాస్టిక్ అస్ఫాల్ట్ సాంకేతికత.",
    "slug": "art-te-050-రాష్ట్రీయం",
    "leadParagraph": "రాష్ట్రంలోని గ్రామీణ, పట్టణ ప్రాంత రహదారులను యుద్ధప్రాతిపదికన మరమ్మతు చేసేందుకు రోడ్లు మరియు భవనాల శాఖ సమగ్ర కార్యాచరణను చేపట్టింది.",
    "summary": "రాష్ట్రంలోని గ్రామీణ, పట్టణ ప్రాంత రహదారులను యుద్ధప్రాతిపదికన మరమ్మతు చేసేందుకు రోడ్లు మరియు భవనాల శాఖ సమగ్ర కార్యాచరణను చేపట్టింది.",
    "synopsis": "రాష్ట్రంలోని గ్రామీణ, పట్టణ ప్రాంత రహదారులను యుద్ధప్రాతిపదికన మరమ్మతు చేసేందుకు రోడ్లు మరియు భవనాల శాఖ సమగ్ర కార్యాచరణను చేపట్టింది.",
    "bodyContent": "వర్షాకాలం ముగియడంతోనే నియోజకవర్గాల వారీగా రోడ్డు మరమ్మతు పనులను ప్రారంభించారు. కాంట్రాక్టర్లకు బిల్లులను ఎస్క్రో ఖాతాల ద్వారా సకాలంలో చెల్లిస్తూ నాణ్యతలో రాజీ పడకుండా థర్డ్ పార్టీ క్వాలిటీ కంట్రోల్ తనిఖీలను తప్పనిసరి చేశారు.",
