    "title": "తెలంగాణ సమగ్ర సామాజిక, ఆర్థిక, విద్య, కుటుంబ సర్వే విజయవంతం",
    "subheadline": "80 వేల మందికి పైగా ఎన్యూమరేటర్ల భాగస్వామ్యం; సంక్షేమ పథకాల సరైన అర్హులకు చేరవేతే లక్ష్యం.",
    "slug": "art-te-051-రాష్ట్రీయం",
    "leadParagraph": "రాష్ట్రంలోని అన్ని వర్గాల ప్రజల జీవన ప్రమాణాలను శాస్త్రీయంగా అంచనా వేసేందుకు తెలంగాణ ప్రభుత్వం చేపట్టిన కుటుంబ సర్వే నిర్ణీత గడువులోగా ముగిసింది.",
    "summary": "రాష్ట్రంలోని అన్ని వర్గాల ప్రజల జీవన ప్రమాణాలను శాస్త్రీయంగా అంచనా వేసేందుకు తెలంగాణ ప్రభుత్వం చేపట్టిన కుటుంబ సర్వే నిర్ణీత గడువులోగా ముగిసింది.",
    "synopsis": "రాష్ట్రంలోని అన్ని వర్గాల ప్రజల జీవన ప్రమాణాలను శాస్త్రీయంగా అంచనా వేసేందుకు తెలంగాణ ప్రభుత్వం చేపట్టిన కుటుంబ సర్వే నిర్ణీత గడువులోగా ముగిసింది.",
    "bodyContent": "ఇంటింటికీ వెళ్లిన సిబ్బంది ప్రజల విద్య, ఉపాధి, ఆదాయ వివరాలను ట్యాబ్ ఆధారిత యాప్‌లో నిక్షిప్తం చేశారు. సేకరించిన సమాచారాన్ని అత్యంత కట్టుదిట్టమైన డేటా సెక్యూరిటీ నిబంధనలతో ప్రభుత్వం భద్రపరిచింది. భవిష్యత్ బడ్జెట్ కేటాయింపులు, పథకాల రూపకల్పనకు ఈ డేటా ఎంతో దోహదపడుతుందని అధికారులు తెలిపారు.",
    "content": "ఇంటింటికీ వెళ్లిన సిబ్బంది ప్రజల విద్య, ఉపాధి, ఆదాయ వివరాలను ట్యాబ్ ఆధారిత యాప్‌లో నిక్షిప్తం చేశారు. సేకరించిన సమాచారాన్ని అత్యంత కట్టుదిట్టమైన డేటా సెక్యూరిటీ నిబంధనలతో ప్రభుత్వం భద్రపరిచింది. భవిష్యత్ బడ్జెట్ కేటాయింపులు, పథకాల రూపకల్పనకు ఈ డేటా ఎంతో దోహదపడుతుందని అధికారులు తెలిపారు.",
