    "title": "రాయలసీమ ప్రాజెక్టులకు జలకళ: గాలేరు-నగరి, హంద్రీనీవా కాలువల ద్వారా చెరువుల నింపుడు",
    "subheadline": "రాయలసీమను సస్యశ్యామలం చేయడమే లక్ష్యం; తాగునీటి ఎద్దడికి శాశ్వత పరిష్కారం.",
