    "summary": "వర్షాభావ ప్రాంతమైన రాయలసీమ జిల్లాలకు కృష్ణా జలాలు పరవళ్లు తొక్కుతూ చేరుకోవడంతో సీమ రైతాంగంలో హర్షాతిరేకాలు వ్యక్తమవుతున్నాయి.",
    "synopsis": "వర్షాభావ ప్రాంతమైన రాయలసీమ జిల్లాలకు కృష్ణా జలాలు పరవళ్లు తొక్కుతూ చేరుకోవడంతో సీమ రైతాంగంలో హర్షాతిరేకాలు వ్యక్తమవుతున్నాయి.",
    "bodyContent": "హంద్రీనీవా సుజల స్రవంతి ప్రధాన కాలువ ద్వారా అనంతపురం, చిత్తూరు జిల్లాల చివరి ఆయకట్టు వరకు నీటిని పారించారు. చెరువులు, కుంటలను ముందుగానే నింపడం వల్ల భూగర్భ జలాలు గణనీయంగా పెరిగాయి. పండ్ల తోటల సాగుదారులకు ఇది సంజీవనిలా మారింది.",
    "content": "హంద్రీనీవా సుజల స్రవంతి ప్రధాన కాలువ ద్వారా అనంతపురం, చిత్తూరు జిల్లాల చివరి ఆయకట్టు వరకు నీటిని పారించారు. చెరువులు, కుంటలను ముందుగానే నింపడం వల్ల భూగర్భ జలాలు గణనీయంగా పెరిగాయి. పండ్ల తోటల సాగుదారులకు ఇది సంజీవనిలా మారింది.",
