    "synopsis": "గ్లోబల్ ఏవియేషన్ పరిశ్రమలో హైదరాబాద్ పేరు ప్రఖ్యాతులు మరింత విస్తరిస్తున్నాయి. వింగ్స్ ఇండియా గ్లోబల్ సదస్సులో భారీ ఒప్పందాలు కుదిరాయి.",
