    "headline": "ఏపీ పోలీస్ శాఖ ఆధునీకరణ: శాంతిభద్రతల పర్యవేక్షణకు హైటెక్ డ్రోన్లు, సీసీ కమాండ్ కంట్రోల్",
    "title": "ఏపీ పోలీస్ శాఖ ఆధునీకరణ: శాంతిభద్రతల పర్యవేక్షణకు హైటెక్ డ్రోన్లు, సీసీ కమాండ్ కంట్రోల్",
