    "summary": "తెలంగాణ సాంస్కృతిక రాజధాని వరంగల్ ప్రజల చిరకాల స్వప్నమైన మామునూరు ఎయిర్‌పోర్టు పునరుద్ధరణ పనులకు అవరోధాలు తొలగిపోయాయి.",
    "synopsis": "తెలంగాణ సాంస్కృతిక రాజధాని వరంగల్ ప్రజల చిరకాల స్వప్నమైన మామునూరు ఎయిర్‌పోర్టు పునరుద్ధరణ పనులకు అవరోధాలు తొలగిపోయాయి.",
    "bodyContent": "కేంద్ర విమానయాన శాఖ ఎయిర్‌పోర్ట్స్ అథారిటీ ఆఫ్ ఇండియా (AAI) బృందం రన్‌వే పొడవును పరిశీలించి పెద్ద విమానాలు దిగేందుకు అనువుగా ప్రణాళికను సిద్ధం చేసింది. హైదరాబాద్, బెంగళూరు, తిరుపతి, ముంబై నగరాలకు త్వరలోనే రెగ్యులర్ కమర్షియల్ విమానాలు ప్రారంభం కానున్నాయి.",
    "content": "కేంద్ర విమానయాన శాఖ ఎయిర్‌పోర్ట్స్ అథారిటీ ఆఫ్ ఇండియా (AAI) బృందం రన్‌వే పొడవును పరిశీలించి పెద్ద విమానాలు దిగేందుకు అనువుగా ప్రణాళికను సిద్ధం చేసింది. హైదరాబాద్, బెంగళూరు, తిరుపతి, ముంబై నగరాలకు త్వరలోనే రెగ్యులర్ కమర్షియల్ విమానాలు ప్రారంభం కానున్నాయి.",
