    "articleId": "art-te-056",
    "tenantId": "tenant-metro-chronicle",
    "headline": "ప్రకృతి వ్యవసాయంలో ఆంధ్రప్రదేశ్ అంతర్జాతీయ ఖ్యాతి: 10 లక్షల మందికి చేరిన సాధికారత",
    "title": "ప్రకృతి వ్యవసాయంలో ఆంధ్రప్రదేశ్ అంతర్జాతీయ ఖ్యాతి: 10 లక్షల మందికి చేరిన సాధికారత",
    "subheadline": "రసాయన రహిత సేంద్రీయ పంటలతో అంతర్జాతీయ మార్కెట్లలో ప్రీమియం ధరలు పొందుతున్న అన్నదాతలు.",
    "slug": "art-te-056-రాష్ట్రీయం",
    "leadParagraph": "పెట్టుబడి లేని ప్రకృతి వ్యవసాయం (APCNF) ద్వారా పర్యావరణ పరిరక్షణతో పాటు రైతుల ఆదాయం రెట్టింపవుతోందని అంతర్జాతీయ వ్యవసాయ సంస్థలు ప్రశంసించాయి.",
    "summary": "పెట్టుబడి లేని ప్రకృతి వ్యవసాయం (APCNF) ద్వారా పర్యావరణ పరిరక్షణతో పాటు రైతుల ఆదాయం రెట్టింపవుతోందని అంతర్జాతీయ వ్యవసాయ సంస్థలు ప్రశంసించాయి.",
    "synopsis": "పెట్టుబడి లేని ప్రకృతి వ్యవసాయం (APCNF) ద్వారా పర్యావరణ పరిరక్షణతో పాటు రైతుల ఆదాయం రెట్టింపవుతోందని అంతర్జాతీయ వ్యవసాయ సంస్థలు ప్రశంసించాయి.",
    "bodyContent": "రసాయన ఎరువులు, పురుగుమందుల స్థానంలో జీవామృతం, దేశీ ఆవు ఆధారిత మిశ్రమాలను ఉపయోగించి పండించిన చిరుధాన్యాలు, కూరగాయలు, బియ్యానికి గల్ఫ్ మరియు యూరోపియన్ దేశాల్లో డిమాండ్ ఏర్పడింది. మహిళా సంఘాల ద్వారా సేంద్రీయ మార్కెట్లను విస్తరించారు.",
    "content": "రసాయన ఎరువులు, పురుగుమందుల స్థానంలో జీవామృతం, దేశీ ఆవు ఆధారిత మిశ్రమాలను ఉపయోగించి పండించిన చిరుధాన్యాలు, కూరగాయలు, బియ్యానికి గల్ఫ్ మరియు యూరోపియన్ దేశాల్లో డిమాండ్ ఏర్పడింది. మహిళా సంఘాల ద్వారా సేంద్రీయ మార్కెట్లను విస్తరించారు.",
