    "title": "ఆంధ్రప్రదేశ్‌లో నూతన పర్యాటక విధానం: సముద్ర తీర లగ్జరీ రిసార్టులు, వాటర్ స్పోర్ట్స్ హబ్‌లు",
    "subheadline": "సూర్యలంక, మంగినపూడి, కళింగపట్నం, భవానీ ఐలాండ్‌ల వద్ద అంతర్జాతీయ ప్రమాణాలతో రిసార్టులు.",
    "slug": "art-te-058-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్ సహజ పర్యాటక సౌందర్యాన్ని విశ్వవ్యాప్తం చేసేందుకు ప్రముఖ హోటల్ గ్రూపులతో ప్రభుత్వం రూ. 6,000 కోట్ల ఒప్పందాలను కుదుర్చుకుంది.",
    "summary": "ఆంధ్రప్రదేశ్ సహజ పర్యాటక సౌందర్యాన్ని విశ్వవ్యాప్తం చేసేందుకు ప్రముఖ హోటల్ గ్రూపులతో ప్రభుత్వం రూ. 6,000 కోట్ల ఒప్పందాలను కుదుర్చుకుంది.",
    "synopsis": "ఆంధ్రప్రదేశ్ సహజ పర్యాటక సౌందర్యాన్ని విశ్వవ్యాప్తం చేసేందుకు ప్రముఖ హోటల్ గ్రూపులతో ప్రభుత్వం రూ. 6,000 కోట్ల ఒప్పందాలను కుదుర్చుకుంది.",
    "bodyContent": "తాజ్, ఒబెరాయ్, హయత్ వంటి సంస్థలు బీచ్ విల్లాలు, కన్వెన్షన్ సెంటర్లను నిర్మించనున్నాయి. విశాఖ, విజయవాడలలో క్రూయిజ్ టూరిజం మరియు స్కైడైవింగ్ వంటి సాహస క్రీడలను ప్రవేశపెట్టడం ద్వారా యువతకు పెద్దఎత్తున ఉపాధి అవకాశాలు లభించనున్నాయి.",
    "content": "తాజ్, ఒబెరాయ్, హయత్ వంటి సంస్థలు బీచ్ విల్లాలు, కన్వెన్షన్ సెంటర్లను నిర్మించనున్నాయి. విశాఖ, విజయవాడలలో క్రూయిజ్ టూరిజం మరియు స్కైడైవింగ్ వంటి సాహస క్రీడలను ప్రవేశపెట్టడం ద్వారా యువతకు పెద్దఎత్తున ఉపాధి అవకాశాలు లభించనున్నాయి.",
