    "headline": "తెలంగాణ చేనేత కార్మికులకు వరం: నేతన్న బీమా పరిహారం పెంపు, నూలుపై 50% రాయితీ",
    "title": "తెలంగాణ చేనేత కార్మికులకు వరం: నేతన్న బీమా పరిహారం పెంపు, నూలుపై 50% రాయితీ",
    "subheadline": "పోచంపల్లి, గద్వాల, సిరిసిల్ల చేనేత కళాఖండాలకు ప్రపంచ మార్కెట్లలో విస్తృత ప్రచారం.",
    "slug": "art-te-059-రాష్ట్రీయం",
    "leadParagraph": "చేనేత రంగాన్ని బలోపేతం చేసేందుకు తెలంగాణ ప్రభుత్వం నేతన్నల సంక్షేమానికి సరికొత్త ప్యాకేజీని అమలులోకి తెచ్చింది.",
    "summary": "చేనేత రంగాన్ని బలోపేతం చేసేందుకు తెలంగాణ ప్రభుత్వం నేతన్నల సంక్షేమానికి సరికొత్త ప్యాకేజీని అమలులోకి తెచ్చింది.",
    "synopsis": "చేనేత రంగాన్ని బలోపేతం చేసేందుకు తెలంగాణ ప్రభుత్వం నేతన్నల సంక్షేమానికి సరికొత్త ప్యాకేజీని అమలులోకి తెచ్చింది.",
    "bodyContent": "చేనేత కార్మికులకు ఇచ్చే ముడిసరుకు సబ్సిడీని రెట్టింపు చేయడంతో పాటు ఇ-కామర్స్ పోర్టళ్ల ద్వారా నేరుగా అమెజాన్, ఫ్లిప్‌కార్ట్‌లలో పోచంపల్లి ఇక్కత్ వస్త్రాలను విక్రయించే ఏర్పాట్లు చేశారు. టెస్టిల్ డిజైనింగ్ ల్యాబ్‌ల ద్వారా యువతను ఆకర్షించే సరికొత్త నమూనాలను రూపొందిస్తున్నారు.",
    "content": "చేనేత కార్మికులకు ఇచ్చే ముడిసరుకు సబ్సిడీని రెట్టింపు చేయడంతో పాటు ఇ-కామర్స్ పోర్టళ్ల ద్వారా నేరుగా అమెజాన్, ఫ్లిప్‌కార్ట్‌లలో పోచంపల్లి ఇక్కత్ వస్త్రాలను విక్రయించే ఏర్పాట్లు చేశారు. టెస్టిల్ డిజైనింగ్ ల్యాబ్‌ల ద్వారా యువతను ఆకర్షించే సరికొత్త నమూనాలను రూపొందిస్తున్నారు.",
