    "headline": "మన్యం గిరిజన గూడేలకు నూరు శాతం సోలార్ విద్యుద్దీకరణ, రోడ్ల సౌకర్యం",
    "title": "మన్యం గిరిజన గూడేలకు నూరు శాతం సోలార్ విద్యుద్దీకరణ, రోడ్ల సౌకర్యం",
    "subheadline": "అరకు, పాడేరు, రంపచోడవరం మన్యంలో తాగునీటి శుద్ధి ప్లాంట్లు; గిరిజన ఉత్పత్తులకు గిట్టుబాటు ధర.",
    "slug": "art-te-060-రాష్ట్రీయం",
    "leadParagraph": "కొండకోనల్లో నివసించే గిరిజనుల జీవితాల్లో వెలుగులు నింపుతూ ఆంధ్రప్రదేశ్ గిరిజన సంక్షేమ శాఖ మౌలిక వసతుల పనులను విజయవంతంగా పూర్తి చేసింది.",
    "summary": "కొండకోనల్లో నివసించే గిరిజనుల జీవితాల్లో వెలుగులు నింపుతూ ఆంధ్రప్రదేశ్ గిరిజన సంక్షేమ శాఖ మౌలిక వసతుల పనులను విజయవంతంగా పూర్తి చేసింది.",
    "synopsis": "కొండకోనల్లో నివసించే గిరిజనుల జీవితాల్లో వెలుగులు నింపుతూ ఆంధ్రప్రదేశ్ గిరిజన సంక్షేమ శాఖ మౌలిక వసతుల పనులను విజయవంతంగా పూర్తి చేసింది.",
    "bodyContent": "గ్రిడ్ విద్యుత్ వెళ్లలేని మారుమూల గిరిజన గ్రామాలకు మైక్రో గ్రిడ్ సోలార్ ప్లాంట్లను అనుసంధానించారు. అరకు కాఫీ, అటవీ తేనె, పసుపు వంటి సేంద్రీయ ఉత్పత్తులను జీసీసీ (GCC) ద్వారా కొనుగోలు చేసి అంతర్జాతీయ మార్కెట్లలో విక్రయించడం ద్వారా గిరిజనుల ఆదాయం పెరిగింది.",
    "content": "గ్రిడ్ విద్యుత్ వెళ్లలేని మారుమూల గిరిజన గ్రామాలకు మైక్రో గ్రిడ్ సోలార్ ప్లాంట్లను అనుసంధానించారు. అరకు కాఫీ, అటవీ తేనె, పసుపు వంటి సేంద్రీయ ఉత్పత్తులను జీసీసీ (GCC) ద్వారా కొనుగోలు చేసి అంతర్జాతీయ మార్కెట్లలో విక్రయించడం ద్వారా గిరిజనుల ఆదాయం పెరిగింది.",
