    "title": "ఆంధ్రప్రదేశ్ నూతన ఎక్సైజ్ పాలసీ అమలు: పారదర్శక లాటరీ ద్వారా మద్యం దుకాణాల కేటాయింపు",
    "subheadline": "ప్రభుత్వ ఖజానాకు దరఖాస్తుల రూపంలోనే రూ. 1800 కోట్ల ఆదాయం; సిండికేట్లకు చెక్.",
    "slug": "art-te-061-రాష్ట్రీయం",
    "leadParagraph": "ప్రజా ధనం లూటీ కాకుండా మద్యం విక్రయాల రంగంలో పూర్తి పారదర్శకతను తీసుకొస్తూ ప్రభుత్వం నూతన విధానాన్ని అమలు చేసింది.",
    "summary": "ప్రజా ధనం లూటీ కాకుండా మద్యం విక్రయాల రంగంలో పూర్తి పారదర్శకతను తీసుకొస్తూ ప్రభుత్వం నూతన విధానాన్ని అమలు చేసింది.",
    "synopsis": "ప్రజా ధనం లూటీ కాకుండా మద్యం విక్రయాల రంగంలో పూర్తి పారదర్శకతను తీసుకొస్తూ ప్రభుత్వం నూతన విధానాన్ని అమలు చేసింది.",
    "bodyContent": "కలెక్టర్ల పర్యవేక్షణలో ప్రజల సమక్షంలో లైవ్ వెబ్‌కాస్టింగ్ ద్వారా దుకాణాల డ్రా నిర్వహించారు. ఎమ్మార్పీ ఉల్లంఘనలపై కఠిన చర్యలు తీసుకునేందుకు క్యూఆర్ కోడ్ ఆధారిత బిల్లింగ్ మిషన్లను తప్పనిసరి చేశారు. బ్రాండెడ్ ఉత్పత్తులను మాత్రమే నిర్ణీత ధరలకు విక్రయించేలా పటిష్ట నిఘా ఏర్పాటు చేశారు.",
    "content": "కలెక్టర్ల పర్యవేక్షణలో ప్రజల సమక్షంలో లైవ్ వెబ్‌కాస్టింగ్ ద్వారా దుకాణాల డ్రా నిర్వహించారు. ఎమ్మార్పీ ఉల్లంఘనలపై కఠిన చర్యలు తీసుకునేందుకు క్యూఆర్ కోడ్ ఆధారిత బిల్లింగ్ మిషన్లను తప్పనిసరి చేశారు. బ్రాండెడ్ ఉత్పత్తులను మాత్రమే నిర్ణీత ధరలకు విక్రయించేలా పటిష్ట నిఘా ఏర్పాటు చేశారు.",
