    "title": "తెలంగాణలో రైతు రుణమాఫీ నిధులు సంపూర్ణం: రూ. 2 లక్షల వరకు రుణాలు రద్దు",
    "subheadline": "రాష్ట్రవ్యాప్తంగా 22 లక్షల రైతు కుటుంబాలకు బ్యాంకుల నుంచి నో-డ్యూ సర్టిఫికెట్లు పంపిణీ.",
    "slug": "art-te-062-రాష్ట్రీయం",
