    "tenantId": "tenant-metro-chronicle",
    "headline": "చారిత్రక చార్మినార్ పాదచారుల ప్రాజెక్ట్ (CPP) పూర్తి: పాతబస్తీకి చారిత్రక వైభవం",
    "title": "చారిత్రక చార్మినార్ పాదచారుల ప్రాజెక్ట్ (CPP) పూర్తి: పాతబస్తీకి చారిత్రక వైభవం",
    "subheadline": "గ్రానైట్ పేవ్‌మెంట్‌లు, హెరిటేజ్ వీధి దీపాలు, బ్యాటరీ వాహనాలతో పర్యాటకులకు ఆహ్లాదం.",
    "slug": "art-te-064-రాష్ట్రీయం",
    "leadParagraph": "ప్రపంచ ప్రఖ్యాతి గాంచిన హైదరాబాద్ చార్మినార్ పరిసర ప్రాంతాలను ట్రాఫిక్ కాలుష్యం లేకుండా పాదచారుల నడకకు అనువుగా సుందరీకరించే పనులు పూర్తయ్యాయి.",
    "summary": "ప్రపంచ ప్రఖ్యాతి గాంచిన హైదరాబాద్ చార్మినార్ పరిసర ప్రాంతాలను ట్రాఫిక్ కాలుష్యం లేకుండా పాదచారుల నడకకు అనువుగా సుందరీకరించే పనులు పూర్తయ్యాయి.",
    "synopsis": "ప్రపంచ ప్రఖ్యాతి గాంచిన హైదరాబాద్ చార్మినార్ పరిసర ప్రాంతాలను ట్రాఫిక్ కాలుష్యం లేకుండా పాదచారుల నడకకు అనువుగా సుందరీకరించే పనులు పూర్తయ్యాయి.",
    "bodyContent": "లాడ్ బజార్, మక్కా మసీదు పరిసరాలను హెరిటేజ్ నడక మార్గంగా తీర్చిదిద్దారు. పర్యాటకులు ఎటువంటి అసౌకర్యం లేకుండా రాత్రి వేళల్లో సైతం చార్మినార్ అందాలను వీక్షించేందుకు ప్రత్యేక విద్యుత్ దీపాలను అమర్చారు. స్థానిక వ్యాపారులకు వాణిజ్యం రెట్టింపైంది.",
    "content": "లాడ్ బజార్, మక్కా మసీదు పరిసరాలను హెరిటేజ్ నడక మార్గంగా తీర్చిదిద్దారు. పర్యాటకులు ఎటువంటి అసౌకర్యం లేకుండా రాత్రి వేళల్లో సైతం చార్మినార్ అందాలను వీక్షించేందుకు ప్రత్యేక విద్యుత్ దీపాలను అమర్చారు. స్థానిక వ్యాపారులకు వాణిజ్యం రెట్టింపైంది.",
