    "headline": "రాష్ట్ర ప్రభుత్వ ఉద్యోగుల సమస్యల పరిష్కారం: పెండింగ్ డీఏ బకాయిల విడుదలకు ఉత్తర్వులు",
    "title": "రాష్ట్ర ప్రభుత్వ ఉద్యోగుల సమస్యల పరిష్కారం: పెండింగ్ డీఏ బకాయిల విడుదలకు ఉత్తర్వులు",
    "subheadline": "ఉద్యోగ సంఘాల హర్షం; పీఆర్సీ కమిషన్ గడువు పొడిగింపు మరియు పెన్షనర్లకు సకాలంలో చెల్లింపులు.",
    "slug": "art-te-065-రాష్ట్రీయం",
    "leadParagraph": "ఆంధ్రప్రదేశ్ రాష్ట్ర ప్రభుత్వ ఉద్యోగులు, ఉపాధ్యాయులు, పెన్షనర్ల చిరకాల డిమాండ్లను పరిష్కరిస్తూ ప్రభుత్వం కీలక జీవోలను జారీ చేసింది.",
    "summary": "ఆంధ్రప్రదేశ్ రాష్ట్ర ప్రభుత్వ ఉద్యోగులు, ఉపాధ్యాయులు, పెన్షనర్ల చిరకాల డిమాండ్లను పరిష్కరిస్తూ ప్రభుత్వం కీలక జీవోలను జారీ చేసింది.",
    "synopsis": "ఆంధ్రప్రదేశ్ రాష్ట్ర ప్రభుత్వ ఉద్యోగులు, ఉపాధ్యాయులు, పెన్షనర్ల చిరకాల డిమాండ్లను పరిష్కరిస్తూ ప్రభుత్వం కీలక జీవోలను జారీ చేసింది.",
    "bodyContent": "ఆర్థిక ఇబ్బందులు ఉన్నప్పటికీ ఉద్యోగుల సంక్షేమానికి ప్రాధాన్యతనిస్తూ డీఏ బకాయిలను ఖాతాల్లో జమ చేయాలని ఆర్థిక శాఖను ఆదేశించారు. ఉద్యోగుల ఆరోగ్య పథకం (EHS) కింద నెట్‌వర్క్ ఆసుపత్రులలో ఉచిత నగదు రహిత చికిత్సలను పటిష్టంగా అమలు చేయనున్నారు.",
    "content": "ఆర్థిక ఇబ్బందులు ఉన్నప్పటికీ ఉద్యోగుల సంక్షేమానికి ప్రాధాన్యతనిస్తూ డీఏ బకాయిలను ఖాతాల్లో జమ చేయాలని ఆర్థిక శాఖను ఆదేశించారు. ఉద్యోగుల ఆరోగ్య పథకం (EHS) కింద నెట్‌వర్క్ ఆసుపత్రులలో ఉచిత నగదు రహిత చికిత్సలను పటిష్టంగా అమలు చేయనున్నారు.",
