    "headline": "విజయవాడ: ఇంద్రకీలాద్రిపై భవానీ దీక్షల విరమణ మహోత్సవానికి సర్వం సిద్ధం",
    "title": "విజయవాడ: ఇంద్రకీలాద్రిపై భవానీ దీక్షల విరమణ మహోత్సవానికి సర్వం సిద్ధం",
    "subheadline": "లక్షలాదిగా తరలిరానున్న భక్తులు; కృష్ణానది ఘాట్ల వద్ద ప్రత్యేక పవిత్ర స్నానాల ఏర్పాట్లు.",
