    "leadParagraph": "విజయవాడ కనకదుర్గమ్మ సన్నిధిలో భవానీ దీక్షల విరమణ ఉత్సవాలకు ఆలయ అధికారులు, నగర పోలీస్ కమిషనరేట్ విస్తృత భద్రతా ఏర్పాట్లు పూర్తి చేసింది.",
    "summary": "విజయవాడ కనకదుర్గమ్మ సన్నిధిలో భవానీ దీక్షల విరమణ ఉత్సవాలకు ఆలయ అధికారులు, నగర పోలీస్ కమిషనరేట్ విస్తృత భద్రతా ఏర్పాట్లు పూర్తి చేసింది.",
    "synopsis": "విజయవాడ కనకదుర్గమ్మ సన్నిధిలో భవానీ దీక్షల విరమణ ఉత్సవాలకు ఆలయ అధికారులు, నగర పోలీస్ కమిషనరేట్ విస్తృత భద్రతా ఏర్పాట్లు పూర్తి చేసింది.",
    "bodyContent": "భక్తులకు ఎండ తగలకుండా క్యూలైన్లలో వాటర్‌ప్రూఫ్ షామియానాలు, ఉచిత మంచినీరు, నిరంతర లడ్డూ ప్రసాదం విక్రయ కౌంటర్లు ఏర్పాటు చేశారు. ప్రకాశం బ్యారేజీ వద్ద ట్రాఫిక్ మళ్లింపులు చేపట్టారు. దుర్గాఘాట్, పద్మావతి ఘాట్ వద్ద గజ ఈతగాళ్లను నిరంతరం అందుబాటులో ఉంచారు.",
