    "title": "తిరుపతి: తిరుమల శ్రీవారి భక్తులకు కల్పతరువుగా నూతన అతిథి గృహ సముదాయాలు ప్రారంభం",
    "subheadline": "టీటీడీ ఆధ్వర్యంలో పీఏసీ-5 ప్రారంభం; సామాన్య భక్తులకు నిమిషాల వ్యవధిలోనే వసతి కేటాయింపు.",
    "slug": "art-te-068-జిల్లా వార్తలు",
    "leadParagraph": "కలియుగ ప్రత్యక్ష దైవం తిరుమల శ్రీ వేంకటేశ్వర స్వామి దర్శనార్థం విచ్చేసే భక్తుల వసతి సౌకర్యార్థం నూతనంగా నిర్మించిన యాత్రికుల వసతి సముదాయం ప్రారంభమైంది.",
    "summary": "కలియుగ ప్రత్యక్ష దైవం తిరుమల శ్రీ వేంకటేశ్వర స్వామి దర్శనార్థం విచ్చేసే భక్తుల వసతి సౌకర్యార్థం నూతనంగా నిర్మించిన యాత్రికుల వసతి సముదాయం ప్రారంభమైంది.",
    "synopsis": "కలియుగ ప్రత్యక్ష దైవం తిరుమల శ్రీ వేంకటేశ్వర స్వామి దర్శనార్థం విచ్చేసే భక్తుల వసతి సౌకర్యార్థం నూతనంగా నిర్మించిన యాత్రికుల వసతి సముదాయం ప్రారంభమైంది.",
    "bodyContent": "ఈ కాంప్లెక్స్‌లో ఒకేసారి 5 వేల మంది భక్తులు బస చేయవచ్చు. లాకర్ల సదుపాయం, శుద్ధి చేసిన తాగునీరు, ఉచిత కల్యాణకట్ట సేవలను అందించనున్నారు. తిరుమలలో ప్లాస్టిక్ నిషేధాన్ని కట్టుదిట్టంగా అమలు చేస్తూ పర్యావరణ పరిరక్షణకు టీటీడీ పెద్దపీట వేస్తోంది.",
    "content": "ఈ కాంప్లెక్స్‌లో ఒకేసారి 5 వేల మంది భక్తులు బస చేయవచ్చు. లాకర్ల సదుపాయం, శుద్ధి చేసిన తాగునీరు, ఉచిత కల్యాణకట్ట సేవలను అందించనున్నారు. తిరుమలలో ప్లాస్టిక్ నిషేధాన్ని కట్టుదిట్టంగా అమలు చేస్తూ పర్యావరణ పరిరక్షణకు టీటీడీ పెద్దపీట వేస్తోంది.",
