    "headline": "గుంటూరు: ఆసియాలోనే అతిపెద్ద మిర్చి యార్డుకు పోటెత్తిన సరుకు, రికార్డు ధరలు",
    "title": "గుంటూరు: ఆసియాలోనే అతిపెద్ద మిర్చి యార్డుకు పోటెత్తిన సరుకు, రికార్డు ధరలు",
    "subheadline": "తేజా రకం క్వింటాల్ రూ. 22,000 పలికిన ధర; అంతర్జాతీయ కొనుగోలుదారుల పోటీ.",
    "slug": "art-te-069-జిల్లా వార్తలు",
    "leadParagraph": "ప్రపంచ ప్రసిద్ధి గాంచిన గుంటూరు వ్యవసాయ మార్కెట్ యార్డులో మిర్చి క్రయవిక్రయాలు సరికొత్త ఉత్సాహంతో సాగుతున్నాయి.",
    "summary": "ప్రపంచ ప్రసిద్ధి గాంచిన గుంటూరు వ్యవసాయ మార్కెట్ యార్డులో మిర్చి క్రయవిక్రయాలు సరికొత్త ఉత్సాహంతో సాగుతున్నాయి.",
    "synopsis": "ప్రపంచ ప్రసిద్ధి గాంచిన గుంటూరు వ్యవసాయ మార్కెట్ యార్డులో మిర్చి క్రయవిక్రయాలు సరికొత్త ఉత్సాహంతో సాగుతున్నాయి.",
    "bodyContent": "చైనా, మలేషియా, శ్రీలంక దేశాల నుంచి ఎగుమతి వ్యాపారులు పెద్ద సంఖ్యలో తరలిరావడంతో ఘాటైన మిర్చి రకాలకు రికార్డు ధరలు లభించాయి. యార్డులో ఈ-నామ్ ద్వారా పారదర్శక కాంటాలు నిర్వహిస్తూ రైతులకు అదే రోజు ఆన్‌లైన్ పేమెంట్లు జమ చేస్తున్నారు.",
    "content": "చైనా, మలేషియా, శ్రీలంక దేశాల నుంచి ఎగుమతి వ్యాపారులు పెద్ద సంఖ్యలో తరలిరావడంతో ఘాటైన మిర్చి రకాలకు రికార్డు ధరలు లభించాయి. యార్డులో ఈ-నామ్ ద్వారా పారదర్శక కాంటాలు నిర్వహిస్తూ రైతులకు అదే రోజు ఆన్‌లైన్ పేమెంట్లు జమ చేస్తున్నారు.",
