    "headline": "కర్నూలు: ఓర్వకల్లు పారిశ్రామిక నోడ్‌లో భారీ సోలార్ సెల్ తయారీ యూనిట్ ఏర్పాటు",
    "title": "కర్నూలు: ఓర్వకల్లు పారిశ్రామిక నోడ్‌లో భారీ సోలార్ సెల్ తయారీ యూనిట్ ఏర్పాటు",
    "subheadline": "రూ. 3,500 కోట్ల పెట్టుబడితో గ్రీన్ కో ప్రాజెక్ట్; రాయలసీమ యువతకు వేలాది ఉద్యోగాలు.",
    "slug": "art-te-070-జిల్లా వార్తలు",
    "leadParagraph": "రాయలసీమ పారిశ్రామిక హబ్‌గా ఎదుగుతున్న కర్నూలు జిల్లా ఓర్వకల్లు మెగా ఇండస్ట్రియల్ పార్కులో అత్యాధునిక తయారీ పరిశ్రమ పనులకు భూమిపూజ జరిగింది.",
    "summary": "రాయలసీమ పారిశ్రామిక హబ్‌గా ఎదుగుతున్న కర్నూలు జిల్లా ఓర్వకల్లు మెగా ఇండస్ట్రియల్ పార్కులో అత్యాధునిక తయారీ పరిశ్రమ పనులకు భూమిపూజ జరిగింది.",
    "synopsis": "రాయలసీమ పారిశ్రామిక హబ్‌గా ఎదుగుతున్న కర్నూలు జిల్లా ఓర్వకల్లు మెగా ఇండస్ట్రియల్ పార్కులో అత్యాధునిక తయారీ పరిశ్రమ పనులకు భూమిపూజ జరిగింది.",
    "bodyContent": "ఓర్వకల్లు విమానాశ్రయం, జాతీయ రహదారి కనెక్టివిటీ ఉండటంతో భారీ పరిశ్రమలు తరలివస్తున్నాయి. సమీపంలోని సోలార్ విద్యుత్ ఉత్పత్తి ఆధారంగా గ్రీన్ ఎనర్జీ ఎక్విప్‌మెంట్‌ను ఇక్కడే తయారు చేసి అంతర్జాతీయ మార్కెట్లకు ఎగుమతి చేయనున్నారు.",
    "content": "ఓర్వకల్లు విమానాశ్రయం, జాతీయ రహదారి కనెక్టివిటీ ఉండటంతో భారీ పరిశ్రమలు తరలివస్తున్నాయి. సమీపంలోని సోలార్ విద్యుత్ ఉత్పత్తి ఆధారంగా గ్రీన్ ఎనర్జీ ఎక్విప్‌మెంట్‌ను ఇక్కడే తయారు చేసి అంతర్జాతీయ మార్కెట్లకు ఎగుమతి చేయనున్నారు.",
