    "headline": "కాకినాడ: డీప్ వాటర్ పోర్ట్ ద్వారా రికార్డు స్థాయిలో ఎల్ఎన్‌జీ మరియు ఎరువుల దిగుమతి",
    "title": "కాకినాడ: డీప్ వాటర్ పోర్ట్ ద్వారా రికార్డు స్థాయిలో ఎల్ఎన్‌జీ మరియు ఎరువుల దిగుమతి",
    "subheadline": "తీరప్రాంతంలో నూతన పెట్రోకెమికల్ కారిడార్ ఏర్పాటుకు సన్నాహాలు ముమ్మరం.",
    "slug": "art-te-071-జిల్లా వార్తలు",
    "leadParagraph": "కాకినాడ డీప్ వాటర్ సీపోర్ట్ సరుకు రవాణాలో అపూర్వ రికార్డును నెలకొల్పింది. ప్రస్తుత ఆర్థిక సంవత్సరంలో కార్గో హ్యాండ్లింగ్ 20 మిలియన్ టన్నులను అధిగమించింది.",
    "summary": "కాకినాడ డీప్ వాటర్ సీపోర్ట్ సరుకు రవాణాలో అపూర్వ రికార్డును నెలకొల్పింది. ప్రస్తుత ఆర్థిక సంవత్సరంలో కార్గో హ్యాండ్లింగ్ 20 మిలియన్ టన్నులను అధిగమించింది.",
    "synopsis": "కాకినాడ డీప్ వాటర్ సీపోర్ట్ సరుకు రవాణాలో అపూర్వ రికార్డును నెలకొల్పింది. ప్రస్తుత ఆర్థిక సంవత్సరంలో కార్గో హ్యాండ్లింగ్ 20 మిలియన్ టన్నులను అధిగమించింది.",
    "bodyContent": "దేశీయ వ్యవసాయానికి అవసరమైన యూరియా, డీఏపీ ఎరువుల రవాణా వేగవంతంగా సాగింది. నౌకాశ్రయానికి అనుసంధానంగా నిర్మించిన రైల్వే సైడింగ్‌లు సరుకును క్షణాల మీద గమ్యస్థానాలకు చేరవేస్తున్నాయి. పారిశ్రామిక కాలుష్య నియంత్రణకు గ్రీన్ బెల్ట్ ఏర్పాటు చేశారు.",
    "content": "దేశీయ వ్యవసాయానికి అవసరమైన యూరియా, డీఏపీ ఎరువుల రవాణా వేగవంతంగా సాగింది. నౌకాశ్రయానికి అనుసంధానంగా నిర్మించిన రైల్వే సైడింగ్‌లు సరుకును క్షణాల మీద గమ్యస్థానాలకు చేరవేస్తున్నాయి. పారిశ్రామిక కాలుష్య నియంత్రణకు గ్రీన్ బెల్ట్ ఏర్పాటు చేశారు.",
