    "subheadline": "వీరభద్ర స్వామి ఆలయానికి యునెస్కో గుర్తింపు దిశగా అడుగులు; పర్యాటకులకు ప్రత్యేక హెరిటేజ్ నడక.",
    "slug": "art-te-073-జిల్లా వార్తలు",
    "leadParagraph": "విజయనగర సామ్రాజ్య శిల్పకళా అద్భుతం లేపాక్షి వీరభద్రాలయం పర్యాటకులను విశేషంగా ఆకర్షిస్తోంది. జిల్లా యంత్రాంగం లేపాక్షి ఉత్సవాలను ఘనంగా నిర్వహించింది.",
    "summary": "విజయనగర సామ్రాజ్య శిల్పకళా అద్భుతం లేపాక్షి వీరభద్రాలయం పర్యాటకులను విశేషంగా ఆకర్షిస్తోంది. జిల్లా యంత్రాంగం లేపాక్షి ఉత్సవాలను ఘనంగా నిర్వహించింది.",
    "synopsis": "విజయనగర సామ్రాజ్య శిల్పకళా అద్భుతం లేపాక్షి వీరభద్రాలయం పర్యాటకులను విశేషంగా ఆకర్షిస్తోంది. జిల్లా యంత్రాంగం లేపాక్షి ఉత్సవాలను ఘనంగా నిర్వహించింది.",
    "bodyContent": "ఆలయంలోని వేలాడే స్తంభం, ఏకశిలా నంది, నాగేంద్రుడి విగ్రహాల చారిత్రక విశేషాలను వివరించేందుకు ఆడియో గైడ్ సిస్టమ్ అందుబాటులోకి వచ్చింది. బెంగళూరు ఎయిర్‌పోర్టుకు సమీపంలో ఉండటంతో విదేశీ పర్యాటకుల తాకిడి పెరిగింది.",
