    "title": "కడప: గండికోట గ్రాండ్ కాన్యన్ వద్ద సాహస క్రీడలు, రోప్‌వే పనులు వేగవంతం",
    "subheadline": "పెన్నా నదీ లోయ అందాలకు అంతర్జాతీయ ఆదరణ; టెంట్ కాటేజీలు, కయాకింగ్ పాయింట్లు సిద్ధం.",
    "slug": "art-te-074-జిల్లా వార్తలు",
