    "summary": "భారతదేశపు గ్రాండ్ కాన్యన్‌గా పేరొందిన గండికోట పర్యాటక కేంద్రం సాహసికులకు స్వర్గధామంగా మారుతోంది. పెన్నా నది లోయపై రోప్‌వే పనులు మొదలయ్యాయి.",
    "synopsis": "భారతదేశపు గ్రాండ్ కాన్యన్‌గా పేరొందిన గండికోట పర్యాటక కేంద్రం సాహసికులకు స్వర్గధామంగా మారుతోంది. పెన్నా నది లోయపై రోప్‌వే పనులు మొదలయ్యాయి.",
    "bodyContent": "గండికోట కోట బురుజులు, చారిత్రక జామా మసీదు, మాధవరాయ ఆలయాలను పురావస్తు శాఖ సంరక్షిస్తోంది. వీకెండ్స్‌లో వేలాది మంది టెక్కీలు క్యాంపింగ్ కోసం తరలివస్తున్నారు. పర్యాటకుల భద్రతకు ప్రత్యేక పోలీసు గస్తీ ఏర్పాటు చేశారు.",
