    "title": "రాజమండ్రి: గోదావరి తీరాన అఖండ హారతి, పుష్కర ఘాట్ల సర్వాంగ సుందరీకరణ",
    "subheadline": "గోదావరి నైట్ టూరిజం ప్రాజెక్ట్ ప్రారంభం; కోటిలింగాల రేవు వద్ద లేజర్ లైట్ అండ్ సౌండ్ షో.",
