    "summary": "సాంస్కృతిక రాజధాని రాజమహేంద్రవరంలో గోదావరి నది తీరాన్ని ప్రముఖ ఆధ్యాత్మిక, పర్యాటక కేంద్రంగా తీర్చిదిద్దుతున్నారు.",
    "synopsis": "సాంస్కృతిక రాజధాని రాజమహేంద్రవరంలో గోదావరి నది తీరాన్ని ప్రముఖ ఆధ్యాత్మిక, పర్యాటక కేంద్రంగా తీర్చిదిద్దుతున్నారు.",
    "bodyContent": "హైదరాబాద్ ట్యాంక్‌బండ్ తరహాలో గోదావరి బండ్‌పై పచ్చదనం, వాకింగ్ ట్రాక్‌లు నిర్మించారు. సాయంత్రం వేళల్లో జరిగే గోదావరి హారతికి వేలాది మంది భక్తులు హాజరవుతున్నారు. హేవలాక్ బ్రిడ్జిని పాదచారుల వారధిగా మార్చే పనులు తుది దశకు చేరాయి.",
    "content": "హైదరాబాద్ ట్యాంక్‌బండ్ తరహాలో గోదావరి బండ్‌పై పచ్చదనం, వాకింగ్ ట్రాక్‌లు నిర్మించారు. సాయంత్రం వేళల్లో జరిగే గోదావరి హారతికి వేలాది మంది భక్తులు హాజరవుతున్నారు. హేవలాక్ బ్రిడ్జిని పాదచారుల వారధిగా మార్చే పనులు తుది దశకు చేరాయి.",
