    "title": "విజయనగరం: బొబ్బిలి పారిశ్రామిక పార్కులో నూతన ఆగ్రో ప్రాసెసింగ్ హబ్ ఏర్పాటు",
    "subheadline": "మామిడి, జీడిమామిడి, పైనాపిల్ ఉత్పత్తులకు ప్రోత్సాహం; రైతు ఉత్పత్తిదారుల సంఘాలకు చేయూత.",
    "slug": "art-te-079-జిల్లా వార్తలు",
    "leadParagraph": "విజయనగరం జిల్లా పారిశ్రామిక రంగంలో అడుగులు ముందుకు వేస్తోంది. బొబ్బిలి గ్రోత్ సెంటర్‌లో మెగా ఫుడ్ పార్కు పనులు పూర్తయ్యాయి.",
    "summary": "విజయనగరం జిల్లా పారిశ్రామిక రంగంలో అడుగులు ముందుకు వేస్తోంది. బొబ్బిలి గ్రోత్ సెంటర్‌లో మెగా ఫుడ్ పార్కు పనులు పూర్తయ్యాయి.",
    "synopsis": "విజయనగరం జిల్లా పారిశ్రామిక రంగంలో అడుగులు ముందుకు వేస్తోంది. బొబ్బిలి గ్రోత్ సెంటర్‌లో మెగా ఫుడ్ పార్కు పనులు పూర్తయ్యాయి.",
    "bodyContent": "రైతులు పండించిన పండ్లను నిల్వ ఉంచేందుకు కోల్డ్ చైన్ నెట్‌వర్క్‌ను నెలకొల్పారు. విదేశీ ఎగుమతుల కోసం జ్యూస్ ప్రాసెసింగ్, ప్యాకింగ్ యూనిట్లు ఏర్పాటు కావడంతో రైతులకు మధ్యవర్తులు లేని లాభాలు దక్కుతున్నాయి.",
