    "headline": "చిత్తూరు: మామిడి, బెల్లం మార్కెట్లో రికార్డు వ్యాపారం, రైతులకు గిట్టుబాటు ధర",
    "title": "చిత్తూరు: మామిడి, బెల్లం మార్కెట్లో రికార్డు వ్యాపారం, రైతులకు గిట్టుబాటు ధర",
    "subheadline": "తోతాపురి మామిడి పల్ప్ పరిశ్రమలకు విదేశీ ఆర్డర్లు; రైతులకు సాంకేతిక మద్దతు.",
    "slug": "art-te-081-జిల్లా వార్తలు",
    "leadParagraph": "చిత్తూరు జిల్లా వ్యవసాయ, ఉద్యానవన రంగాలలో ఈ ఏడాది లాభాల పంట పండుతోంది. మార్కెట్ యార్డులకు భారీగా ఉత్పత్తులు తరలివచ్చాయి.",
    "summary": "చిత్తూరు జిల్లా వ్యవసాయ, ఉద్యానవన రంగాలలో ఈ ఏడాది లాభాల పంట పండుతోంది. మార్కెట్ యార్డులకు భారీగా ఉత్పత్తులు తరలివచ్చాయి.",
    "synopsis": "చిత్తూరు జిల్లా వ్యవసాయ, ఉద్యానవన రంగాలలో ఈ ఏడాది లాభాల పంట పండుతోంది. మార్కెట్ యార్డులకు భారీగా ఉత్పత్తులు తరలివచ్చాయి.",
    "bodyContent": "జిల్లాలోని 30కి పైగా మామిడి పల్ప్ ప్రాసెసింగ్ యూనిట్లు పూర్తి సామర్థ్యంతో నడుస్తున్నాయి. అమెరికా, గల్ఫ్ దేశాలకు పల్ప్ ఎగుమతి అవుతోంది. రైతులకు ప్రభుత్వ మద్దతు ధర దక్కేలా జిల్లా కలెక్టర్ ప్రత్యేక పర్యవేక్షణ బృందాలను నియమించారు.",
    "content": "జిల్లాలోని 30కి పైగా మామిడి పల్ప్ ప్రాసెసింగ్ యూనిట్లు పూర్తి సామర్థ్యంతో నడుస్తున్నాయి. అమెరికా, గల్ఫ్ దేశాలకు పల్ప్ ఎగుమతి అవుతోంది. రైతులకు ప్రభుత్వ మద్దతు ధర దక్కేలా జిల్లా కలెక్టర్ ప్రత్యేక పర్యవేక్షణ బృందాలను నియమించారు.",
