    "title": "మదనపల్లె: టమోటా మార్కెట్‌కు పోటెత్తిన పంట, రైతులకు దక్కిన ఆశాజనక ధరలు",
    "subheadline": "ఆసియాలోనే ప్రసిద్ధి గాంచిన టమోటా యార్డులో నిత్యం వందలాది లారీల లోడింగ్.",
    "slug": "art-te-082-జిల్లా వార్తలు",
    "leadParagraph": "అన్నమయ్య జిల్లా మదనపల్లె వ్యవసాయ మార్కెట్ యార్డులో టమోటా క్రయవిక్రయాలు ఊపందుకున్నాయి. దక్షిణాది రాష్ట్రాల వ్యాపారులు పోటీపడి కొనుగోలు చేస్తున్నారు.",
    "summary": "అన్నమయ్య జిల్లా మదనపల్లె వ్యవసాయ మార్కెట్ యార్డులో టమోటా క్రయవిక్రయాలు ఊపందుకున్నాయి. దక్షిణాది రాష్ట్రాల వ్యాపారులు పోటీపడి కొనుగోలు చేస్తున్నారు.",
    "synopsis": "అన్నమయ్య జిల్లా మదనపల్లె వ్యవసాయ మార్కెట్ యార్డులో టమోటా క్రయవిక్రయాలు ఊపందుకున్నాయి. దక్షిణాది రాష్ట్రాల వ్యాపారులు పోటీపడి కొనుగోలు చేస్తున్నారు.",
    "bodyContent": "రైతులకు నష్టం కలగకుండా కోల్డ్ స్టోరేజ్ వసతులను యార్డులో అందుబాటులోకి తెచ్చారు. టమోటా కెచప్, ప్యూరీ తయారీ యూనిట్లను స్థానికంగా నెలకొల్పేందుకు ప్రభుత్వం రాయితీలు ప్రకటించింది.",
    "content": "రైతులకు నష్టం కలగకుండా కోల్డ్ స్టోరేజ్ వసతులను యార్డులో అందుబాటులోకి తెచ్చారు. టమోటా కెచప్, ప్యూరీ తయారీ యూనిట్లను స్థానికంగా నెలకొల్పేందుకు ప్రభుత్వం రాయితీలు ప్రకటించింది.",
