    "headline": "నంద్యాల: బనగానపల్లె నవాబుల కాలం నాటి మామిడికి అంతర్జాతీయ గుర్తింపు, ఎగుమతులు",
    "title": "నంద్యాల: బనగానపల్లె నవాబుల కాలం నాటి మామిడికి అంతర్జాతీయ గుర్తింపు, ఎగుమతులు",
    "subheadline": "బనగానపల్లి మామిడికి పెరిగిన విదేశీ డిమాండ్; రైతులకు జీఐ ట్యాగ్ రిజిస్ట్రేషన్ సర్టిఫికెట్లు.",
    "slug": "art-te-085-జిల్లా వార్తలు",
    "leadParagraph": "భౌగోళిక గుర్తింపు (GI Tag) పొందిన బనగానపల్లె మామిడి పండ్ల సీజన్ లాభదాయకంగా ప్రారంభమైంది.",
    "summary": "భౌగోళిక గుర్తింపు (GI Tag) పొందిన బనగానపల్లె మామిడి పండ్ల సీజన్ లాభదాయకంగా ప్రారంభమైంది.",
    "synopsis": "భౌగోళిక గుర్తింపు (GI Tag) పొందిన బనగానపల్లె మామిడి పండ్ల సీజన్ లాభదాయకంగా ప్రారంభమైంది.",
    "bodyContent": "కర్నూలు, నంద్యాల ప్రాంతాల్లో పండే ఈ రకానికి ఉండే తియ్యదనం, నాణ్యత ప్రపంచ ప్రసిద్ధి చెందింది. అమెరికా, లండన్‌లలోని ప్రవాస భారతీయులకు ఆన్‌లైన్ ద్వారా ఎక్స్‌ప్రెస్ కార్గో ద్వారా నేరుగా సరఫరా చేసే నెట్‌వర్క్ అమల్లోకి వచ్చింది.",
    "content": "కర్నూలు, నంద్యాల ప్రాంతాల్లో పండే ఈ రకానికి ఉండే తియ్యదనం, నాణ్యత ప్రపంచ ప్రసిద్ధి చెందింది. అమెరికా, లండన్‌లలోని ప్రవాస భారతీయులకు ఆన్‌లైన్ ద్వారా ఎక్స్‌ప్రెస్ కార్గో ద్వారా నేరుగా సరఫరా చేసే నెట్‌వర్క్ అమల్లోకి వచ్చింది.",
