    "headline": "పుట్టపర్తి: ప్రశాంతి నిలయంలో ఘనంగా విశ్వశాంతి దినోత్సవ వేడుకలు",
    "title": "పుట్టపర్తి: ప్రశాంతి నిలయంలో ఘనంగా విశ్వశాంతి దినోత్సవ వేడుకలు",
    "subheadline": "విదేశాల నుంచి వేలాదిగా తరలివచ్చిన భక్తులు; సేవా కార్యక్రమాల్లో పాల్గొన్న ప్రముఖులు.",
    "slug": "art-te-086-జిల్లా వార్తలు",
    "leadParagraph": "ప్రపంచ ప్రఖ్యాత ఆధ్యాత్మిక కేంద్రం పుట్టపర్తి ప్రశాంతి నిలయంలో సత్యసాయి బాబా ఆశీస్సులతో మానవ సేవా ఉత్సవాలు అత్యంత భక్తిశ్రద్ధలతో జరిగాయి.",
    "summary": "ప్రపంచ ప్రఖ్యాత ఆధ్యాత్మిక కేంద్రం పుట్టపర్తి ప్రశాంతి నిలయంలో సత్యసాయి బాబా ఆశీస్సులతో మానవ సేవా ఉత్సవాలు అత్యంత భక్తిశ్రద్ధలతో జరిగాయి.",
    "synopsis": "ప్రపంచ ప్రఖ్యాత ఆధ్యాత్మిక కేంద్రం పుట్టపర్తి ప్రశాంతి నిలయంలో సత్యసాయి బాబా ఆశీస్సులతో మానవ సేవా ఉత్సవాలు అత్యంత భక్తిశ్రద్ధలతో జరిగాయి.",
    "bodyContent": "ఉచిత సూపర్ స్పెషాలిటీ ఆసుపత్రుల ద్వారా పేదలకు అందుతున్న వైద్య సేవలను ప్రముఖులు కొనియాడారు. సాయి గీతా ఆడిటోరియంలో సాంస్కృతిక ప్రదర్శనలు, భజన కార్యక్రమాలు నిర్వహించారు. నిరుపేదలకు దుస్తులు, నిత్యావసర వస్తువులను పంపిణీ చేశారు.",
    "content": "ఉచిత సూపర్ స్పెషాలిటీ ఆసుపత్రుల ద్వారా పేదలకు అందుతున్న వైద్య సేవలను ప్రముఖులు కొనియాడారు. సాయి గీతా ఆడిటోరియంలో సాంస్కృతిక ప్రదర్శనలు, భజన కార్యక్రమాలు నిర్వహించారు. నిరుపేదలకు దుస్తులు, నిత్యావసర వస్తువులను పంపిణీ చేశారు.",
