    "title": "వరంగల్: కాకతీయ మెగా టెక్స్‌టైల్ పార్క్‌లో కొరియన్ కంపెనీల వస్త్ర తయారీ ప్లాంట్లు ప్రారంభం",
    "subheadline": "రూ. 1,800 కోట్ల పెట్టుబడితో యంగ్ ఒన్ కార్పొరేషన్ యూనిట్; 12,000 మంది స్థానిక మహిళలకు ఉపాధి.",
    "slug": "art-te-087-జిల్లా వార్తలు",
    "leadParagraph": "తెలంగాణ వస్త్ర పరిశ్రమ రాజధానిగా ఎదుగుతున్న వరంగల్ జిల్లా కాకతీయ మెగా టెక్స్‌టైల్ పార్క్ అంతర్జాతీయ ఉత్పత్తిని ప్రారంభించింది.",
    "summary": "తెలంగాణ వస్త్ర పరిశ్రమ రాజధానిగా ఎదుగుతున్న వరంగల్ జిల్లా కాకతీయ మెగా టెక్స్‌టైల్ పార్క్ అంతర్జాతీయ ఉత్పత్తిని ప్రారంభించింది.",
    "synopsis": "తెలంగాణ వస్త్ర పరిశ్రమ రాజధానిగా ఎదుగుతున్న వరంగల్ జిల్లా కాకతీయ మెగా టెక్స్‌టైల్ పార్క్ అంతర్జాతీయ ఉత్పత్తిని ప్రారంభించింది.",
    "bodyContent": "క్రీడా దుస్తులు, అంతర్జాతీయ బ్రాండెడ్ జాకెట్లను ఇక్కడి నుంచే తయారు చేసి యూరప్ మార్కెట్లకు ఎగుమతి చేయనున్నారు. స్థానిక మహిళలకు టైలరింగ్, డిజైనింగ్‌లో ఆధునిక శిక్షణ ఇచ్చి నేరుగా ఉద్యోగాలు కల్పించారు.",
    "content": "క్రీడా దుస్తులు, అంతర్జాతీయ బ్రాండెడ్ జాకెట్లను ఇక్కడి నుంచే తయారు చేసి యూరప్ మార్కెట్లకు ఎగుమతి చేయనున్నారు. స్థానిక మహిళలకు టైలరింగ్, డిజైనింగ్‌లో ఆధునిక శిక్షణ ఇచ్చి నేరుగా ఉద్యోగాలు కల్పించారు.",
