    "headline": "కరీంనగర్: మానేరు రివర్ ఫ్రంట్ కేబుల్ బ్రిడ్జి వద్ద లేజర్ అండ్ ఫౌంటైన్ షో ప్రారంభం",
    "title": "కరీంనగర్: మానేరు రివర్ ఫ్రంట్ కేబుల్ బ్రిడ్జి వద్ద లేజర్ అండ్ ఫౌంటైన్ షో ప్రారంభం",
    "subheadline": "ఉత్తర తెలంగాణ పర్యాటక ఆకర్షణగా లోయర్ మానేరు డ్యామ్; నైట్ సఫారీకి సన్నాహాలు.",
    "slug": "art-te-088-జిల్లా వార్తలు",
    "leadParagraph": "కరీంనగర్ నగరానికి మణిహారంగా నిలిచిన కేబుల్ స్టేడ్ బ్రిడ్జి వద్ద అత్యాధునిక మ్యూజికల్ ఫౌంటైన్ మరియు లేజర్ షోలను పర్యాటకుల కోసం ప్రారంభించారు.",
    "summary": "కరీంనగర్ నగరానికి మణిహారంగా నిలిచిన కేబుల్ స్టేడ్ బ్రిడ్జి వద్ద అత్యాధునిక మ్యూజికల్ ఫౌంటైన్ మరియు లేజర్ షోలను పర్యాటకుల కోసం ప్రారంభించారు.",
    "synopsis": "కరీంనగర్ నగరానికి మణిహారంగా నిలిచిన కేబుల్ స్టేడ్ బ్రిడ్జి వద్ద అత్యాధునిక మ్యూజికల్ ఫౌంటైన్ మరియు లేజర్ షోలను పర్యాటకుల కోసం ప్రారంభించారు.",
    "bodyContent": "రోజూ సాయంత్రం వేలాది మంది కుటుంబ సమేతంగా వచ్చి ఆహ్లాదకరమైన సమయాన్ని గడుపుతున్నారు. తీగల వంతెన విద్యుత్ దీపాల కాంతులు నీటిలో ప్రతిబింబిస్తూ కనువిందు చేస్తున్నాయి. మానేరు తీరంలో బోటింగ్ సౌకర్యాలను విస్తరించారు.",
    "content": "రోజూ సాయంత్రం వేలాది మంది కుటుంబ సమేతంగా వచ్చి ఆహ్లాదకరమైన సమయాన్ని గడుపుతున్నారు. తీగల వంతెన విద్యుత్ దీపాల కాంతులు నీటిలో ప్రతిబింబిస్తూ కనువిందు చేస్తున్నాయి. మానేరు తీరంలో బోటింగ్ సౌకర్యాలను విస్తరించారు.",
