    "summary": "ఖమ్మం జిల్లా అన్నదాతలకు సాగునీటి తిప్పలు తప్పాయి. పాలేరు జలాశయం నుంచి ప్రధాన కాలువలకు మంత్రులు సాగునీటిని విడుదల చేశారు.",
    "synopsis": "ఖమ్మం జిల్లా అన్నదాతలకు సాగునీటి తిప్పలు తప్పాయి. పాలేరు జలాశయం నుంచి ప్రధాన కాలువలకు మంత్రులు సాగునీటిని విడుదల చేశారు.",
    "bodyContent": "ఆయకట్టు చివర భూములకు సైతం నీరు అందేలా ఇరిగేషన్ ఇంజనీర్లు ప్రత్యేక షెడ్యూల్ రూపొందించారు. వరి, మిర్చి పంటలకు సమృద్ధిగా నీరు లభించనుండటంతో దిగుబడులు ఆశాజనకంగా ఉంటాయని వ్యవసాయ శాఖ అంచనా వేసింది.",
