    "headline": "నిజామాబాద్: జాతీయ పసుపు బోర్డు ద్వారా రైతులకు అత్యాధునిక విత్తనాలు, పరిశోధనలు",
    "title": "నిజామాబాద్: జాతీయ పసుపు బోర్డు ద్వారా రైతులకు అత్యాధునిక విత్తనాలు, పరిశోధనలు",
    "subheadline": "పసుపు ఎగుమతులకు సరికొత్త ప్రోత్సాహం; నిజామాబాద్ మార్కెట్‌లో క్వింటాల్ రూ. 16,000 మార్కు.",
    "slug": "art-te-090-జిల్లా వార్తలు",
    "leadParagraph": "తెలంగాణ పసుపు రైతులకు ఎంతో కాలంగా కలగా ఉన్న జాతీయ పసుపు బోర్డు (National Turmeric Board) కార్యకలాపాలు ఊపందుకున్నాయి.",
    "summary": "తెలంగాణ పసుపు రైతులకు ఎంతో కాలంగా కలగా ఉన్న జాతీయ పసుపు బోర్డు (National Turmeric Board) కార్యకలాపాలు ఊపందుకున్నాయి.",
    "synopsis": "తెలంగాణ పసుపు రైతులకు ఎంతో కాలంగా కలగా ఉన్న జాతీయ పసుపు బోర్డు (National Turmeric Board) కార్యకలాపాలు ఊపందుకున్నాయి.",
    "bodyContent": "పసుపులో కర్కుమిన్ శాతాన్ని పెంచే మేలైన విత్తనాలను రైతులకు ఉచితంగా పంపిణీ చేశారు. ప్రాసెసింగ్ యూనిట్లకు 50 శాతం సబ్సిడీని కల్పిస్తూ గల్ఫ్, యూరోప్ దేశాలకు నిజామాబాద్ పసుపును నేరుగా ఎగుమతి చేసే సదుపాయం కల్పించారు.",
    "content": "పసుపులో కర్కుమిన్ శాతాన్ని పెంచే మేలైన విత్తనాలను రైతులకు ఉచితంగా పంపిణీ చేశారు. ప్రాసెసింగ్ యూనిట్లకు 50 శాతం సబ్సిడీని కల్పిస్తూ గల్ఫ్, యూరోప్ దేశాలకు నిజామాబాద్ పసుపును నేరుగా ఎగుమతి చేసే సదుపాయం కల్పించారు.",
