    "title": "నల్గొండ: నాగార్జునసాగర్ వద్ద బుద్ధవనం అంతర్జాతీయ బౌద్ధ పర్యాటక కేంద్రం విస్తరణ",
    "subheadline": "ఆగ్నేయాసియా దేశాల నుంచి తరలివస్తున్న బౌద్ధ భిక్షువులు; ధ్యాన కేంద్రాల నిర్మాణం పూర్తి.",
