    "summary": "చారిత్రక నాగార్జునకొండ సమీపంలో నిర్మించిన ఆసియాలోనే అతిపెద్ద బౌద్ధ థీమ్ పార్క్ బుద్ధవనం అంతర్జాతీయ యాత్రికులను ఆకర్షిస్తోంది.",
    "synopsis": "చారిత్రక నాగార్జునకొండ సమీపంలో నిర్మించిన ఆసియాలోనే అతిపెద్ద బౌద్ధ థీమ్ పార్క్ బుద్ధవనం అంతర్జాతీయ యాత్రికులను ఆకర్షిస్తోంది.",
    "bodyContent": "మహాస్థూపం, బుద్ధుడి జీవిత ఘట్టాలను వివరించే శిల్పకళా సంపద చూపరులను ఆకట్టుకుంటోంది. శ్రీలంక, థాయ్‌లాండ్, జపాన్ దేశాల బౌద్ధ సంఘాలు ఇక్కడ ప్రత్యేక ఆశ్రమాలు నిర్మించేందుకు ముందుకొచ్చాయి.",
    "content": "మహాస్థూపం, బుద్ధుడి జీవిత ఘట్టాలను వివరించే శిల్పకళా సంపద చూపరులను ఆకట్టుకుంటోంది. శ్రీలంక, థాయ్‌లాండ్, జపాన్ దేశాల బౌద్ధ సంఘాలు ఇక్కడ ప్రత్యేక ఆశ్రమాలు నిర్మించేందుకు ముందుకొచ్చాయి.",
