    "title": "మహబూబ్‌నగర్: పాలమూరు-రంగారెడ్డి ఎత్తిపోతల సర్జిపూల్ ద్వారా ట్రయల్ రన్ విజయవంతం",
    "subheadline": "నార్లాపూర్ వద్ద భారీ బాహుబలి మోటార్లతో నీటి పంపింగ్; సీమగడ్డకు తీరనున్న తాగునీటి కష్టాలు.",
    "slug": "art-te-092-జిల్లా వార్తలు",
