    "subheadline": "రూ. 2,100 కోట్ల పెట్టుబడితో మహీంద్రా ఈవీ యూనిట్ విస్తరణ; వేలాది మంది ఇంజనీర్లకు ఉపాధి.",
    "slug": "art-te-093-జిల్లా వార్తలు",
    "leadParagraph": "జాతీయ పారిశ్రామిక ఉత్పత్తుల కేంద్రంగా మారుతున్న సంగారెడ్డి జిల్లా జహీరాబాద్‌లో సరికొత్త తరం ఎలక్ట్రిక్ ఆటోమొబైల్ తయారీ ప్లాంట్ ప్రారంభమైంది.",
    "summary": "జాతీయ పారిశ్రామిక ఉత్పత్తుల కేంద్రంగా మారుతున్న సంగారెడ్డి జిల్లా జహీరాబాద్‌లో సరికొత్త తరం ఎలక్ట్రిక్ ఆటోమొబైల్ తయారీ ప్లాంట్ ప్రారంభమైంది.",
    "synopsis": "జాతీయ పారిశ్రామిక ఉత్పత్తుల కేంద్రంగా మారుతున్న సంగారెడ్డి జిల్లా జహీరాబాద్‌లో సరికొత్త తరం ఎలక్ట్రిక్ ఆటోమొబైల్ తయారీ ప్లాంట్ ప్రారంభమైంది.",
    "bodyContent": "బ్యాటరీ ప్యాక్‌లు, ఈవీ మోటార్లను స్థానికంగానే తయారు చేయనున్నారు. ఇండస్ట్రియల్ పార్కులో అంతర్జాతీయ స్థాయి రోడ్లు, 24 గంటల పవర్ గ్రిడ్ సౌకర్యాలు కల్పించారు.",
    "content": "బ్యాటరీ ప్యాక్‌లు, ఈవీ మోటార్లను స్థానికంగానే తయారు చేయనున్నారు. ఇండస్ట్రియల్ పార్కులో అంతర్జాతీయ స్థాయి రోడ్లు, 24 గంటల పవర్ గ్రిడ్ సౌకర్యాలు కల్పించారు.",
