    "summary": "ప్రకృతి అందాలకు నిలయమైన ఆదిలాబాద్ జిల్లాలోని జలపాతాలు కనువిందు చేస్తున్నాయి. సెలవు దినాల్లో పర్యాటకులు పెద్దసంఖ్యలో తరలివస్తున్నారు.",
    "synopsis": "ప్రకృతి అందాలకు నిలయమైన ఆదిలాబాద్ జిల్లాలోని జలపాతాలు కనువిందు చేస్తున్నాయి. సెలవు దినాల్లో పర్యాటకులు పెద్దసంఖ్యలో తరలివస్తున్నారు.",
