    "subheadline": "భారతదేశంలోనే అత్యున్నత సాంకేతికత; రికార్డు స్థాయిలో బొగ్గు వెలికితీత లక్ష్యం.",
    "slug": "art-te-095-జిల్లా వార్తలు",
