    "headline": "భద్రాచలం: శ్రీ సీతారామచంద్రస్వామి ఆలయంలో గోదావరి నిత్య హారతి, భక్తుల సందడి",
    "title": "భద్రాచలం: శ్రీ సీతారామచంద్రస్వామి ఆలయంలో గోదావరి నిత్య హారతి, భక్తుల సందడి",
    "subheadline": "దక్షిణ అయోధ్యగా విరాజిల్లుతున్న పుణ్యక్షేత్రం; ఆలయ మాస్టర్ ప్లాన్ విస్తరణ పనులకు ఆమోదం.",
    "slug": "art-te-096-జిల్లా వార్తలు",
    "leadParagraph": "భక్త రామదాసు నిర్మించిన చారిత్రక భద్రాచలం క్షేత్రంలో గోదావరి తీరంలో రోజూ సాయంత్రం జరిగే ప్రత్యేక నదీ హారతి భక్తులను మంత్రముగ్ధులను చేస్తోంది.",
    "summary": "భక్త రామదాసు నిర్మించిన చారిత్రక భద్రాచలం క్షేత్రంలో గోదావరి తీరంలో రోజూ సాయంత్రం జరిగే ప్రత్యేక నదీ హారతి భక్తులను మంత్రముగ్ధులను చేస్తోంది.",
    "synopsis": "భక్త రామదాసు నిర్మించిన చారిత్రక భద్రాచలం క్షేత్రంలో గోదావరి తీరంలో రోజూ సాయంత్రం జరిగే ప్రత్యేక నదీ హారతి భక్తులను మంత్రముగ్ధులను చేస్తోంది.",
    "bodyContent": "ఆలయ ప్రాకారాల విస్తరణ, యాత్రికుల బస కోసం నూతన కాటేజీల నిర్మాణం ముమ్మరంగా సాగుతోంది. నదీ స్నానాలు ఆచరించే భక్తుల రక్షణ కోసం పటిష్టమైన రేలింగ్‌లను ఏర్పాటు చేశారు.",
    "content": "ఆలయ ప్రాకారాల విస్తరణ, యాత్రికుల బస కోసం నూతన కాటేజీల నిర్మాణం ముమ్మరంగా సాగుతోంది. నదీ స్నానాలు ఆచరించే భక్తుల రక్షణ కోసం పటిష్టమైన రేలింగ్‌లను ఏర్పాటు చేశారు.",
