    "summary": "సూర్యాపేట జిల్లా పరిధిలోని మూసీ మీడియం ఇరిగేషన్ ప్రాజెక్టు పూర్తిస్థాయి నీటిమట్టానికి చేరుకోవడంతో కాలువలకు నీటిని విడుదల చేశారు.",
    "synopsis": "సూర్యాపేట జిల్లా పరిధిలోని మూసీ మీడియం ఇరిగేషన్ ప్రాజెక్టు పూర్తిస్థాయి నీటిమట్టానికి చేరుకోవడంతో కాలువలకు నీటిని విడుదల చేశారు.",
    "bodyContent": "రైతులు పండించిన వరి ధాన్యాన్ని కొనుగోలు చేసేందుకు జిల్లావ్యాప్తంగా ఐకేపీ కొనుగోలు కేంద్రాలను సిద్ధం చేశారు. రైతులకు 24 గంటల్లో మద్దతు ధర సొమ్ము ఖాతాల్లో జమయ్యేలా చర్యలు తీసుకున్నారు.",
