    "summary": "శతాబ్దాల చరిత్ర కలిగిన గద్వాల పట్టు చేనేత వస్త్ర పరిశ్రమ జాతీయ స్థాయిలో అరుదైన అవార్డులను దక్కించుకుంది.",
    "synopsis": "శతాబ్దాల చరిత్ర కలిగిన గద్వాల పట్టు చేనేత వస్త్ర పరిశ్రమ జాతీయ స్థాయిలో అరుదైన అవార్డులను దక్కించుకుంది.",
    "bodyContent": "చేనేత కళాకారులు రూపొందించిన వినూత్న కుట్టుబొమ్మల డిజైన్లు, ప్యూర్ సిల్క్ నాణ్యత ఫ్యాషన్ పరిశ్రమను ఆకట్టుకుంది. నేతన్నలకు బ్యాంక్ రుణాలు, హెల్త్ ఇన్సూరెన్స్ కార్డులను కలెక్టర్ చేతుల మీదుగా అందజేశారు.",
